// تجميع كل السوالف في قائمة واحدة مع فئاتها
window.getAllSpyTopics = function() {
  const all = [];
  Object.entries(window.SPY_LOCATIONS).forEach(([cat, words]) => {
    words.forEach(w => all.push({ word: w, category: cat }));
  });
  // إضافة سوالف المستخدم المخصصة
  try {
    const custom = JSON.parse(localStorage.getItem('spy_custom_topics') || '[]');
    custom.forEach(w => all.push({ word: w, category: 'سوالفي' }));
  } catch (e) {}
  return all;
};

if (typeof console !== 'undefined') {
  let t = 0;
  Object.values(window.SPY_LOCATIONS).forEach(arr => t += arr.length);
  console.log('Spy topics loaded:', t, 'سالفة في', Object.keys(window.SPY_LOCATIONS).length, 'فئات');
}

