// ===== الدخول للعبة =====
function openSpyGame() {
  playSound('click');
  SpyState.screen = 'setup';
  SpyState.players = [];
  SpyState.topic = null;
  SpyState.revealIndex = 0;
  SpyState.revealShown = false;
  if (SpyState.timerInterval) { clearInterval(SpyState.timerInterval); SpyState.timerInterval = null; }
  State.screen = 'spy';
  render();
}

