function renderSpySetup() {
  const cats = Object.keys(window.SPY_LOCATIONS || {});
  const customCount = (() => { try { return JSON.parse(localStorage.getItem('spy_custom_topics')||'[]').length; } catch(e){ return 0; } })();

  return `
    <div class="screen">
      <div class="arena-header">
        <button class="btn btn-ghost btn-sm" onclick="navigate('hub')">‹ رجوع</button>
        <h2 class="arena-header-title">الجاسوس</h2>
        <div style="width:60px"></div>
      </div>

      <div class="spy-intro-card">
        <div class="spy-intro-icon">🕵️</div>
        <div class="spy-intro-text">
          الكل يعرف "السالفة" إلا الجاسوس! اسألوا بعض أسئلة ذكية، واكشفوا الجاسوس قبل ما يخمّن الكلمة.
        </div>
      </div>

      <div class="card" style="margin-bottom:14px">
        <label class="spy-label">عدد اللاعبين</label>
        <div class="spy-stepper">
          <button class="spy-step-btn" onclick="adjustSpyPlayers(-1)">−</button>
          <span class="spy-step-value">${SpyState.numPlayers}</span>
          <button class="spy-step-btn" onclick="adjustSpyPlayers(1)">+</button>
        </div>
        <div class="spy-hint">من 3 إلى 8 لاعبين</div>
      </div>

      <div class="card" style="margin-bottom:14px">
        <label class="spy-label">عدد الجواسيس</label>
        <div class="spy-stepper">
          <button class="spy-step-btn" onclick="adjustSpySpies(-1)">−</button>
          <span class="spy-step-value">${SpyState.numSpies}</span>
          <button class="spy-step-btn" onclick="adjustSpySpies(1)">+</button>
        </div>
        <div class="spy-hint">${SpyState.numSpies >= Math.ceil(SpyState.numPlayers/2) ? '⚠️ عدد كبير من الجواسيس' : 'الأفضل جاسوس واحد لكل 4-5 لاعبين'}</div>
      </div>

      <div class="card" style="margin-bottom:14px">
        <label class="spy-label">أسماء اللاعبين</label>
        <div id="spy-names" style="display:flex;flex-direction:column;gap:8px;margin-top:10px">
          ${Array.from({length: SpyState.numPlayers}, (_, i) => `
            <input class="spy-name-input" placeholder="لاعب ${i+1}"
                   value="${SpyState.players[i] ? escapeHtml(SpyState.players[i].name) : ''}"
                   oninput="updateSpyName(${i}, this.value)"/>
          `).join('')}
        </div>
      </div>

      <div class="card" style="margin-bottom:14px">
        <label class="spy-label">فئة السوالف</label>
        <select class="spy-select" onchange="SpyState.category=this.value" style="margin-top:10px">
          <option value="mixed">🎲 متنوّع (الكل)</option>
          ${cats.map(c => `<option value="${c}" ${SpyState.category===c?'selected':''}>${c}</option>`).join('')}
          ${customCount > 0 ? `<option value="سوالفي">⭐ سوالفي (${customCount})</option>` : ''}
        </select>
      </div>

      <div class="card" style="margin-bottom:14px">
        <label class="spy-toggle-row">
          <span class="spy-label" style="margin:0">مؤقت لمرحلة الأسئلة</span>
          <input type="checkbox" ${SpyState.useTimer?'checked':''} onchange="SpyState.useTimer=this.checked;render()"/>
        </label>
        ${SpyState.useTimer ? `
          <div class="spy-stepper" style="margin-top:12px">
            <button class="spy-step-btn" onclick="adjustSpyTimer(-1)">−</button>
            <span class="spy-step-value">${SpyState.timerMinutes} دقائق</span>
            <button class="spy-step-btn" onclick="adjustSpyTimer(1)">+</button>
          </div>
        ` : '<div class="spy-hint">اللاعبون يقررون متى يصوّتون</div>'}
      </div>

      <div class="card" style="margin-bottom:14px">
        <label class="spy-label">عدد الجولات في المباراة</label>
        <div class="spy-stepper">
          <button class="spy-step-btn" onclick="adjustSpyRounds(-1)">−</button>
          <span class="spy-step-value">${SpyState.totalRounds} جولات</span>
          <button class="spy-step-btn" onclick="adjustSpyRounds(1)">+</button>
        </div>
        <div class="spy-hint">من يجمع أكثر نقاط عبر الجولات يفوز</div>
      </div>

      <button class="btn btn-primary btn-full" style="padding:18px;font-size:18px;margin-top:6px" onclick="startSpyMatch()">
        ابدأ المباراة 🕵️
      </button>

      <button class="btn btn-secondary btn-full" style="margin-top:10px" onclick="openSpyCustomTopics()">
        ➕ أضف سوالفك الخاصة
      </button>
    </div>
  `;
}

function adjustSpyPlayers(d) {
  playSound('click');
  SpyState.numPlayers = Math.max(3, Math.min(8, SpyState.numPlayers + d));
  // تأكد عدد الجواسيس منطقي
  if (SpyState.numSpies >= SpyState.numPlayers) SpyState.numSpies = 1;
  render();
}
function adjustSpySpies(d) {
  playSound('click');
  const max = Math.max(1, Math.floor(SpyState.numPlayers / 2));
  SpyState.numSpies = Math.max(1, Math.min(max, SpyState.numSpies + d));
  render();
}
function adjustSpyTimer(d) {
  playSound('click');
  SpyState.timerMinutes = Math.max(2, Math.min(15, SpyState.timerMinutes + d));
  render();
}
function adjustSpyRounds(d) {
  playSound('click');
  SpyState.totalRounds = Math.max(3, Math.min(10, SpyState.totalRounds + d));
  render();
}
function updateSpyName(i, val) {
  if (!SpyState.players[i]) SpyState.players[i] = {};
  SpyState.players[i].name = val;
}

// ===== بدء اللعبة: توزيع الأدوار =====
function startSpyGame() {
  // تجهيز الأسماء
  const names = [];
  for (let i = 0; i < SpyState.numPlayers; i++) {
    const n = (SpyState.players[i] && SpyState.players[i].name || '').trim();
    names.push(n || `لاعب ${i+1}`);
  }

  // اختيار السالفة
  let pool = window.getAllSpyTopics();
  if (SpyState.category && SpyState.category !== 'mixed') {
    const filtered = pool.filter(t => t.category === SpyState.category);
    if (filtered.length) pool = filtered;
  }
  SpyState.topic = pool[Math.floor(Math.random() * pool.length)];

  // توزيع الجواسيس عشوائياً
  const spyIndices = new Set();
  while (spyIndices.size < SpyState.numSpies) {
    spyIndices.add(Math.floor(Math.random() * SpyState.numPlayers));
  }

  SpyState.players = names.map((name, i) => ({
    name,
    avatar: SPY_AVATARS[i % SPY_AVATARS.length],
    isSpy: spyIndices.has(i),
  }));

  // من يبدأ السؤال (لاعب عشوائي)
  SpyState.startPlayer = SpyState.players[Math.floor(Math.random() * SpyState.numPlayers)].name;

  SpyState.revealIndex = 0;
  SpyState.revealShown = false;
  SpyState._roundScored = false;
  SpyState.votedFor = null;
  SpyState.screen = 'reveal';
  playSound('start');
  render();
}

// ===== مرحلة الكشف (مرّر الجهاز) =====
function renderSpyReveal() {
  const player = SpyState.players[SpyState.revealIndex];
  const isLast = SpyState.revealIndex === SpyState.players.length - 1;

  if (!SpyState.revealShown) {
    // شاشة "اضغط لرؤية دورك"
    return `
      <div class="screen spy-reveal-screen">
        <div class="spy-pass-card">
          <div class="spy-pass-avatar">${player.avatar}</div>
          <div class="spy-pass-name">${escapeHtml(player.name)}</div>
          <div class="spy-pass-instruction">مرّر الجهاز لـ ${escapeHtml(player.name)}<br>ثم اضغط لرؤية دورك سرّاً</div>
          <button class="btn btn-primary btn-full" style="padding:18px;font-size:18px;margin-top:24px" onclick="showSpyRole()">
            👁️ اكشف دوري
          </button>
        </div>
      </div>
    `;
  }

  // شاشة عرض الدور
  const roleHtml = player.isSpy
    ? `<div class="spy-role-card spy-role-spy">
         <div class="spy-role-icon">🕵️</div>
         <div class="spy-role-title">أنت الجاسوس!</div>
         <div class="spy-role-desc">أنت <b>برا السالفة</b>. اسمع الأسئلة وحاول تخمّن الكلمة، وموّه عشان ما يكشفونك!</div>
       </div>`
    : `<div class="spy-role-card spy-role-citizen">
         <div class="spy-role-icon">✅</div>
         <div class="spy-role-title">أنت داخل السالفة</div>
         <div class="spy-role-label">الكلمة السرية:</div>
         <div class="spy-role-word">${escapeHtml(SpyState.topic.word)}</div>
         <div class="spy-role-cat">${escapeHtml(SpyState.topic.category)}</div>
       </div>`;

  return `
    <div class="screen spy-reveal-screen">
      ${roleHtml}
      <button class="btn btn-primary btn-full" style="padding:18px;font-size:18px;margin-top:24px" onclick="nextSpyReveal()">
        ${isLast ? 'الكل شافوا أدوارهم ✓' : 'فهمت، التالي ←'}
      </button>
      <div class="spy-reveal-progress">${SpyState.revealIndex + 1} / ${SpyState.players.length}</div>
    </div>
  `;
}

function showSpyRole() {
  playSound('flip');
  SpyState.revealShown = true;
  render();
}

function nextSpyReveal() {
  playSound('click');
  if (SpyState.revealIndex < SpyState.players.length - 1) {
    SpyState.revealIndex++;
    SpyState.revealShown = false;
    render();
  } else {
    // بدء مرحلة الأسئلة
    startSpyPlaying();
  }
}

// ===== مرحلة الأسئلة =====
function startSpyPlaying() {
  SpyState.screen = 'playing';
  if (SpyState.useTimer) {
    SpyState.timeLeft = SpyState.timerMinutes * 60;
    if (SpyState.timerInterval) clearInterval(SpyState.timerInterval);
    SpyState.timerInterval = setInterval(() => {
      SpyState.timeLeft--;
      const el = document.getElementById('spy-timer');
      if (el) el.textContent = formatSpyTime(SpyState.timeLeft);
      if (SpyState.timeLeft <= 0) {
        clearInterval(SpyState.timerInterval);
        SpyState.timerInterval = null;
        playSound('timeup');
        startSpyVoting();
      }
    }, 1000);
  }
  playSound('start');
  render();
}

function formatSpyTime(s) {
  const m = Math.floor(s / 60);
  const sec = s % 60;
  return `${m}:${sec < 10 ? '0' : ''}${sec}`;
}

function renderSpyPlaying() {
  return `
    <div class="screen">
      <div class="game-topbar">
        <button class="btn-home-exit" onclick="confirmExitSpy()" title="خروج">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M9 22V12h6v10"/></svg>
        </button>
        <div class="round-indicator">مرحلة الأسئلة</div>
        <div style="width:42px"></div>
      </div>

      ${SpyState.useTimer ? `
        <div class="spy-timer-big" id="spy-timer">${formatSpyTime(SpyState.timeLeft)}</div>
      ` : '<div class="spy-timer-big spy-no-timer">∞</div>'}

      <div class="spy-play-card">
        <div class="spy-play-start">
          يبدأ السؤال: <b>${escapeHtml(SpyState.startPlayer)}</b>
        </div>
        <div class="spy-play-rules">
          <div class="spy-rule">🗣️ كل لاعب يسأل آخر سؤالاً عن السالفة بالدور</div>
          <div class="spy-rule">🤔 جاوبوا بذكاء: أثبتوا إنكم تعرفون دون ما تكشفون الكلمة</div>
          <div class="spy-rule">🕵️ الجاسوس يحاول يخمّن، والباقون يكشفونه</div>
        </div>
      </div>

      <div class="spy-players-strip">
        ${SpyState.players.map(p => `
          <div class="spy-player-chip">
            <span>${p.avatar}</span>
            <span>${escapeHtml(p.name)}</span>
          </div>
        `).join('')}
      </div>

      <button class="btn btn-primary btn-full" style="padding:18px;font-size:18px;margin-top:18px" onclick="startSpyVoting()">
        انتهت الأسئلة — صوّتوا الآن 🗳️
      </button>
    </div>
  `;
}

// ===== مرحلة التصويت =====
function startSpyVoting() {
  if (SpyState.timerInterval) { clearInterval(SpyState.timerInterval); SpyState.timerInterval = null; }
  SpyState.screen = 'voting';
  SpyState.votedFor = null;
  playSound('click');
  render();
}

function renderSpyVoting() {
  return `
    <div class="screen">
      <div class="arena-header">
        <h2 class="arena-header-title" style="margin:0 auto">التصويت</h2>
      </div>

      <div class="spy-vote-prompt">
        مين الجاسوس برأيكم؟ اتفقوا وصوّتوا على لاعب واحد
      </div>

      <div class="spy-vote-grid">
        ${SpyState.players.map((p, i) => `
          <div class="spy-vote-card ${SpyState.votedFor === i ? 'selected' : ''}" onclick="selectSpyVote(${i})">
            <div class="spy-vote-avatar">${p.avatar}</div>
            <div class="spy-vote-name">${escapeHtml(p.name)}</div>
          </div>
        `).join('')}
      </div>

      <button class="btn btn-primary btn-full" style="padding:18px;font-size:18px;margin-top:18px"
              ${SpyState.votedFor === null ? 'disabled style="opacity:0.5;padding:18px;font-size:18px;margin-top:18px"' : ''}
              onclick="confirmSpyVote()">
        تأكيد التصويت
      </button>
    </div>
  `;
}

function selectSpyVote(i) {
  playSound('click');
  SpyState.votedFor = i;
  render();
}

function confirmSpyVote() {
  if (SpyState.votedFor === null) return;
  const voted = SpyState.players[SpyState.votedFor];
  if (voted.isSpy) {
    // كشفوا جاسوساً - يعطى فرصة تخمين الكلمة
    SpyState.screen = 'spyGuess';
  } else {
    // صوّتوا غلط - الجاسوس يفوز
    SpyState.screen = 'result';
    SpyState.winResult = 'spy_hidden';
  }
  playSound('click');
  render();
}

// ===== فرصة الجاسوس لتخمين الكلمة =====
function renderSpyGuess() {
  const spies = SpyState.players.filter(p => p.isSpy);
  const topicPool = window.getAllSpyTopics().filter(t =>
    SpyState.category === 'mixed' || !SpyState.category ? true : t.category === SpyState.category
  );
  // خيارات التخمين: الكلمة الصحيحة + 7 عشوائية
  const others = topicPool.filter(t => t.word !== SpyState.topic.word);
  const shuffledOthers = shuffle(others).slice(0, 7).map(t => t.word);
  const options = shuffle([SpyState.topic.word, ...shuffledOthers]);

  return `
    <div class="screen">
      <div class="arena-header">
        <h2 class="arena-header-title" style="margin:0 auto">فرصة الجاسوس</h2>
      </div>

      <div class="spy-caught-card">
        <div class="spy-caught-icon">🎯</div>
        <div class="spy-caught-title">كشفتوا الجاسوس!</div>
        <div class="spy-caught-spies">${spies.map(s => `${s.avatar} ${escapeHtml(s.name)}`).join('، ')}</div>
        <div class="spy-caught-desc">لكن للجاسوس فرصة أخيرة: إذا خمّن السالفة الصحيحة، يفوز!</div>
      </div>

      <div class="spy-guess-prompt">وش السالفة (الكلمة السرية)؟</div>
      <div class="spy-guess-grid">
        ${options.map(w => `
          <button class="spy-guess-option" onclick="submitSpyGuess('${escapeHtml(w).replace(/'/g, "\\'")}')">
            ${escapeHtml(w)}
          </button>
        `).join('')}
      </div>
    </div>
  `;
}

function submitSpyGuess(word) {
  SpyState.spyGuess = word;
  if (word === SpyState.topic.word) {
    SpyState.winResult = 'spy_guessed';
  } else {
    SpyState.winResult = 'citizens';
  }
  SpyState.screen = 'result';
  playSound(word === SpyState.topic.word ? 'win' : 'correct');
  render();
}

// ===== احتساب نقاط الجولة =====
function awardSpyRoundPoints() {
  // نمنح النقاط مرة واحدة لكل جولة (نتفادى التكرار عند إعادة الرسم)
  if (SpyState._roundScored) return;
  SpyState._roundScored = true;

  const spies = SpyState.players.filter(p => p.isSpy).map(p => p.name);
  const citizens = SpyState.players.filter(p => !p.isSpy).map(p => p.name);

  // تأكد أن كل اللاعبين لهم مدخل نقاط
  SpyState.players.forEach(p => {
    if (SpyState.scores[p.name] === undefined) SpyState.scores[p.name] = 0;
  });

  if (SpyState.winResult === 'citizens') {
    // المجموعة فازت: كل غير-جاسوس +1
    citizens.forEach(n => SpyState.scores[n] += 1);
  } else {
    // الجاسوس فاز (سواء بالاختباء أو التخمين): كل جاسوس +2
    spies.forEach(n => SpyState.scores[n] += 2);
  }
}

// ===== النتيجة =====
function renderSpyResult() {
  awardSpyRoundPoints();
  const spies = SpyState.players.filter(p => p.isSpy);
  let title, icon, desc, color;

  if (SpyState.winResult === 'spy_hidden') {
    icon = '🕵️'; color = 'var(--danger)';
    title = 'الجاسوس فاز!';
    desc = `صوّتّم على البريء! الجاسوس كان: ${spies.map(s => `${s.avatar} ${escapeHtml(s.name)}`).join('، ')}`;
  } else if (SpyState.winResult === 'spy_guessed') {
    icon = '🎯'; color = 'var(--danger)';
    title = 'الجاسوس فاز!';
    desc = `كشفتوه لكنه خمّن السالفة الصحيحة "${escapeHtml(SpyState.topic.word)}" وفاز!`;
  } else {
    icon = '🏆'; color = 'var(--success)';
    title = 'المجموعة فازت!';
    desc = `كشفتوا الجاسوس وما عرف السالفة! ${spies.map(s => `${s.avatar} ${escapeHtml(s.name)}`).join('، ')}`;
  }

  const isLastRound = SpyState.round >= SpyState.totalRounds;

  // ترتيب اللاعبين حسب النقاط
  const ranked = [...SpyState.players].sort((a, b) =>
    (SpyState.scores[b.name] || 0) - (SpyState.scores[a.name] || 0));

  const scoreboardHtml = `
    <div class="spy-scoreboard">
      <div class="spy-scoreboard-title">النقاط بعد الجولة ${SpyState.round} من ${SpyState.totalRounds}</div>
      ${ranked.map((p, i) => `
        <div class="spy-score-row ${i === 0 ? 'spy-score-leader' : ''}">
          <span class="spy-score-rank">${i + 1}</span>
          <span class="spy-score-player">${p.avatar} ${escapeHtml(p.name)}</span>
          <span class="spy-score-pts">${SpyState.scores[p.name] || 0}</span>
        </div>
      `).join('')}
    </div>
  `;

  if (isLastRound) {
    // المباراة انتهت - شاشة البطل
    const champion = ranked[0];
    const maxScore = SpyState.scores[champion.name] || 0;
    const winners = ranked.filter(p => (SpyState.scores[p.name] || 0) === maxScore);
    return `
      <div class="screen">
        <div class="spy-result-card" style="border-color:${color}">
          <div class="spy-result-icon">${icon}</div>
          <div class="spy-result-title" style="color:${color}">${title}</div>
          <div class="spy-result-desc">${desc}</div>
          <div class="spy-result-reveal">
            <div class="spy-result-word-label">السالفة كانت</div>
            <div class="spy-result-word">${escapeHtml(SpyState.topic.word)}</div>
          </div>
        </div>

        <div class="spy-champion-card">
          <div class="spy-champion-crown">👑</div>
          <div class="spy-champion-label">بطل المباراة</div>
          <div class="spy-champion-name">${winners.map(w => `${w.avatar} ${escapeHtml(w.name)}`).join(' و ')}</div>
          <div class="spy-champion-score">${maxScore} نقطة</div>
        </div>

        ${scoreboardHtml}

        <button class="btn btn-primary btn-full" style="padding:18px;font-size:18px;margin-top:18px" onclick="startSpyMatch()">
          🔄 مباراة جديدة (نفس اللاعبين)
        </button>
        <button class="btn btn-secondary btn-full" style="margin-top:10px" onclick="openSpyGame()">
          إعداد جديد
        </button>
        <button class="btn btn-ghost btn-full" style="margin-top:10px" onclick="navigate('hub')">
          الرئيسية
        </button>
      </div>
    `;
  }

  // جولة عادية - نكمل للجولة التالية
  return `
    <div class="screen">
      <div class="spy-result-card" style="border-color:${color}">
        <div class="spy-result-icon">${icon}</div>
        <div class="spy-result-title" style="color:${color}">${title}</div>
        <div class="spy-result-desc">${desc}</div>
        <div class="spy-result-reveal">
          <div class="spy-result-word-label">السالفة كانت</div>
          <div class="spy-result-word">${escapeHtml(SpyState.topic.word)}</div>
          <div class="spy-result-cat">${escapeHtml(SpyState.topic.category)}</div>
        </div>
      </div>

      ${scoreboardHtml}

      <button class="btn btn-primary btn-full" style="padding:18px;font-size:18px;margin-top:18px" onclick="nextSpyRound()">
        الجولة التالية (${SpyState.round + 1}/${SpyState.totalRounds}) ←
      </button>
      <button class="btn btn-ghost btn-full" style="margin-top:10px" onclick="confirmExitSpy()">
        إنهاء المباراة
      </button>
    </div>
  `;
}

// بدء مباراة جديدة (تصفير النقاط)
function startSpyMatch() {
  playSound('click');
  SpyState.scores = {};
  SpyState.round = 1;
  SpyState.matchActive = true;
  const names = SpyState.players.map(p => p.name);
  SpyState.numPlayers = names.length;
  SpyState.players = names.map((name, i) => ({ name, avatar: SPY_AVATARS[i % SPY_AVATARS.length] }));
  startSpyGame();
}

// الجولة التالية في نفس المباراة (يحتفظ بالنقاط)
function nextSpyRound() {
  playSound('click');
  SpyState.round += 1;
  const names = SpyState.players.map(p => p.name);
  SpyState.numPlayers = names.length;
  SpyState.players = names.map((name, i) => ({ name, avatar: SPY_AVATARS[i % SPY_AVATARS.length] }));
  startSpyGame();
}

function replaySpyGame() {
  // للتوافق: يبدأ مباراة جديدة
  startSpyMatch();
}

function confirmExitSpy() {
  playSound('click');
  if (confirm('هل تريد الخروج من لعبة الجاسوس؟')) {
    if (SpyState.timerInterval) { clearInterval(SpyState.timerInterval); SpyState.timerInterval = null; }
    navigate('hub');
  }
}

// ===== سوالف مخصصة =====
function openSpyCustomTopics() {
  playSound('click');
  SpyState.screen = 'custom';
  render();
}

function renderSpyCustom() {
  let custom = [];
  try { custom = JSON.parse(localStorage.getItem('spy_custom_topics') || '[]'); } catch(e) {}

  return `
    <div class="screen">
      <div class="arena-header">
        <button class="btn btn-ghost btn-sm" onclick="SpyState.screen='setup';render()">‹ رجوع</button>
        <h2 class="arena-header-title">سوالفي</h2>
        <div style="width:60px"></div>
      </div>

      <div class="card" style="margin-bottom:14px">
        <label class="spy-label">أضف سالفة جديدة</label>
        <div style="display:flex;gap:8px;margin-top:10px">
          <input id="spy-new-topic" class="spy-name-input" placeholder="مثال: المقهى، الطيارة..." style="flex:1"/>
          <button class="btn btn-primary btn-sm" onclick="addSpyCustomTopic()">إضافة</button>
        </div>
      </div>

      ${custom.length ? `
        <div class="card">
          <label class="spy-label">سوالفك (${custom.length})</label>
          <div style="display:flex;flex-direction:column;gap:8px;margin-top:10px">
            ${custom.map((w, i) => `
              <div class="spy-custom-item">
                <span>${escapeHtml(w)}</span>
                <button class="btn btn-danger btn-sm" onclick="removeSpyCustomTopic(${i})">×</button>
              </div>
            `).join('')}
          </div>
        </div>
      ` : '<div class="spy-empty">ما أضفت سوالف بعد. أضف كلماتك المفضلة!</div>'}
    </div>
  `;
}

function addSpyCustomTopic() {
  const input = document.getElementById('spy-new-topic');
  if (!input) return;
  const val = input.value.trim();
  if (!val) return;
  let custom = [];
  try { custom = JSON.parse(localStorage.getItem('spy_custom_topics') || '[]'); } catch(e) {}
  if (!custom.includes(val)) {
    custom.push(val);
    localStorage.setItem('spy_custom_topics', JSON.stringify(custom));
    playSound('correct');
  }
  render();
}

function removeSpyCustomTopic(i) {
  let custom = [];
  try { custom = JSON.parse(localStorage.getItem('spy_custom_topics') || '[]'); } catch(e) {}
  custom.splice(i, 1);
  localStorage.setItem('spy_custom_topics', JSON.stringify(custom));
  playSound('click');
  render();
}

// ===== موجّه العرض =====
function renderSpy() {
  switch (SpyState.screen) {
    case 'setup': return renderSpySetup();
    case 'reveal': return renderSpyReveal();
    case 'playing': return renderSpyPlaying();
    case 'voting': return renderSpyVoting();
    case 'spyGuess': return renderSpyGuess();
    case 'result': return renderSpyResult();
    case 'custom': return renderSpyCustom();
    default: return renderSpySetup();
  }
}

