function loadCustomCategories() {
  try {
    const cats = JSON.parse(localStorage.getItem('esalni_v6_custom_cats') || '[]');
    cats.forEach(c => {
      if (!CATEGORIES.find(x => x.id === c.id)) {
        CATEGORIES.push({ ...c, isCustom: true });
      }
    });
  } catch(e) {}
}
function saveCustomCategories() {
  const custom = CATEGORIES.filter(c => c.isCustom).map(c => ({ id: c.id, name: c.name, icon: c.icon, color: c.color }));
  try { localStorage.setItem('esalni_v6_custom_cats', JSON.stringify(custom)); } catch(e) {}
}

