const Stats = {
  xp: 0,
  totalGames: 0,
  wins: 0,
  correctAnswers: 0,
  wrongAnswers: 0,
  lifelinesUsed: 0,
  totalScore: 0,
  hardAnswered: 0,
  perfectCategories: 0,
  winNoLifelines: 0,
  currentStreak: 0,
  bestStreak: 0,
  categoriesPlayed: {},
  unlockedAchievements: [],
};

function loadStats() {
  try {
    const saved = localStorage.getItem('esalni_v6_stats');
    if (saved) {
      const data = JSON.parse(saved);
      Object.assign(Stats, data);
    }
  } catch(e) {}
}

function saveStats() {
  try { localStorage.setItem('esalni_v6_stats', JSON.stringify(Stats)); } catch(e) {}
}

function getCurrentLevel() {
  let current = LEVELS[0];
  for (const lvl of LEVELS) {
    if (Stats.xp >= lvl.minXP) current = lvl;
    else break;
  }
  return current;
}

function getNextLevel() {
  const idx = LEVELS.findIndex(l => l.name === getCurrentLevel().name);
  return LEVELS[idx + 1] || null;
}

function getLevelProgress() {
  const current = getCurrentLevel();
  const next = getNextLevel();
  if (!next) return 100;
  const currentXP = Stats.xp - current.minXP;
  const neededXP = next.minXP - current.minXP;
  return Math.min(100, (currentXP / neededXP) * 100);
}

function addXP(amount, reason = '') {
  const oldLevel = getCurrentLevel();
  Stats.xp += amount;
  saveStats();
  const newLevel = getCurrentLevel();
  if (newLevel.name !== oldLevel.name) {
    setTimeout(() => showLevelUpModal(newLevel), 500);
  }
  return amount;
}

function checkAchievements() {
  const newlyUnlocked = [];
  ACHIEVEMENTS.forEach(ach => {
    if (!Stats.unlockedAchievements.includes(ach.id) && ach.check(Stats)) {
      Stats.unlockedAchievements.push(ach.id);
      Stats.xp += ach.xp;
      newlyUnlocked.push(ach);
    }
  });
  if (newlyUnlocked.length > 0) {
    saveStats();
    setTimeout(() => showAchievementsModal(newlyUnlocked), 800);
  }
  return newlyUnlocked;
}

