const State = {
  screen: 'theme-select',
  theme: 'light',
  hasSeenOnboarding: false,
  questionsDB: {},
  modesDB: {},
  setup: {
    teams: [
      { name: 'الفريق الأول', avatar: '🦁', color: '#cd7f32', score: 0 },
      { name: 'الفريق الثاني', avatar: '🐯', color: '#cc5500', score: 0 },
    ],
    categories: [],
    timePerQuestion: 45,
  },
  game: null,
  gameHistory: [],
  lastSetup: null,
  hasUnfinishedGame: false,
  timerInterval: null,
};

function saveGameProgress() {
  if (!State.game) return;
  try {
    const snapshot = {
      grid: State.game.grid,
      categories: State.game.categories,
      currentTeam: State.game.currentTeam,
      teams: State.game.teams,
      timePerQuestion: State.game.timePerQuestion,
      history: State.game.history,
      startTime: State.game.startTime,
      savedAt: Date.now(),
    };
    localStorage.setItem('esalni_v6_unfinished_game', JSON.stringify(snapshot));
    State.hasUnfinishedGame = true;
  } catch(e) {}
}

function loadGameProgress() {
  try {
    const saved = localStorage.getItem('esalni_v6_unfinished_game');
    if (!saved) return null;
    const data = JSON.parse(saved);
    // إذا اللعبة قديمة (أكثر من 24 ساعة) نحذفها
    if (Date.now() - data.savedAt > 24 * 60 * 60 * 1000) {
      localStorage.removeItem('esalni_v6_unfinished_game');
      return null;
    }
    return data;
  } catch(e) { return null; }
}

function clearGameProgress() {
  try {
    localStorage.removeItem('esalni_v6_unfinished_game');
    State.hasUnfinishedGame = false;
  } catch(e) {}
}

function resumeGame() {
  const saved = loadGameProgress();
  if (!saved) return false;
  State.game = {
    ...saved,
    currentQuestion: null,
    currentCat: null,
    currentLevel: null,
    timeLeft: 0,
    selectedAnswer: null,
    showAnswer: false,
    showHint: false,
    eliminatedAnswers: [],
    doubleActive: false,
  };
  navigate('grid');
  return true;
}

function saveLastSetup() {
  try {
    const setup = {
      teams: State.setup.teams.map(t => ({ ...t, score: 0 })),
      categories: [...State.setup.categories],
      timePerQuestion: State.setup.timePerQuestion,
    };
    localStorage.setItem('esalni_v6_last_setup', JSON.stringify(setup));
    State.lastSetup = setup;
  } catch(e) {}
}

function loadLastSetup() {
  try {
    const saved = localStorage.getItem('esalni_v6_last_setup');
    if (!saved) return null;
    return JSON.parse(saved);
  } catch(e) { return null; }
}

function replayLastGame() {
  const last = State.lastSetup || loadLastSetup();
  if (!last) {
    showToast('لا توجد لعبة سابقة');
    return;
  }
  State.setup = {
    teams: last.teams.map(t => ({ ...t, score: 0 })),
    categories: [...last.categories],
    timePerQuestion: last.timePerQuestion,
  };
  startGame();
}

