// ============================================================
// Helpers
// ============================================================
function buildQuestionsDB() {
  const merged = {};
  // الأسئلة الأصلية (4 ملفات)
  const parts = [window.QUESTIONS_PART1, window.QUESTIONS_PART2, window.QUESTIONS_PART3, window.QUESTIONS_PART4].filter(Boolean);
  parts.forEach(p => {
    Object.keys(p).forEach(cat => {
      if (!merged[cat]) merged[cat] = [];
      merged[cat] = merged[cat].concat(p[cat]);
    });
  });

  // الأسئلة الجديدة (500 سؤال) من ملفات part5-part10
  const newParts = [
    window.QUESTIONS_SAUDI_NEW,        // 120 سعودي
    window.QUESTIONS_ISLAMIC,           // 80 إسلامي
    window.QUESTIONS_SPORTS_NEW,        // 60 رياضة
    window.QUESTIONS_ENTERTAINMENT_NEW, // 60 سينما + 50 موسيقى
    window.QUESTIONS_FOOD_GEO_NEW,      // 50 طعام + 50 جغرافيا
    window.QUESTIONS_LITERATURE_NEW,    // 30 أدب
    window.QUESTIONS_EXP1,              // 220: سعودية + تكنولوجيا + علوم
    window.QUESTIONS_EXP2,              // 230: مدن + حيوانات + مشاهير + أعلام
    window.QUESTIONS_EXP3,              // 300: ألغاز + ثقافة + تاريخ + سينما + رياضة
    window.QUESTIONS_HARD,             // ~90: أسئلة صعبة 500-600 نقطة
    window.QUESTIONS_EXCEL_HARD,       // 154: أسئلة خبير من ملف Excel
    window.QUESTIONS_HARDER_MYSTERY_GENERAL, // 30: ألغاز وثقافة عامة محققة المصدر
    window.QUESTIONS_EXPERT_PLUS,            // أسئلة خبير جديدة للفئات التي تنقصها (رياضة/سينما/طعام/موسيقى/مشاهير)
  ].filter(Boolean);
  newParts.forEach(p => {
    Object.keys(p).forEach(cat => {
      if (!merged[cat]) merged[cat] = [];
      merged[cat] = merged[cat].concat(p[cat]);
    });
  });

  // الأسئلة المضافة من المستخدم محلياً
  try {
    const custom = JSON.parse(localStorage.getItem('esalni_v6_custom') || '{}');
    Object.keys(custom).forEach(cat => {
      if (!merged[cat]) merged[cat] = [];
      merged[cat] = merged[cat].concat(custom[cat]);
    });
  } catch(e) {}

  // إزالة الأسئلة المكررة (حسب نص السؤال المُطبَّع + الإجابة) - يحافظ على أول ظهور
  Object.keys(merged).forEach(cat => {
    const seen = new Set();
    merged[cat] = merged[cat].filter(q => {
      // نطبّع النص: نزيل الترقيم، نوحّد المسافات، نوحّد المرادفات الشائعة
      const qText = (q.q || '').trim()
        .replace(/[«»"'""'']/g, '')
        .replace(/[؟?\.\،,]/g, '')
        .replace(/من\s+(هو|هي)\s+/g, 'من ')
        .replace(/من\s+(كاتب|مؤلف|كاتبة|مؤلفة|مخرج|مخرجة)/g, 'من-كاتب')
        .replace(/\s(رواية|ديوان|كتاب|قصة|مسرحية|فيلم|مسلسل|أغنية)\s/g, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
      // المفتاح هو نص السؤال المُطبَّع فقط: يجمع تلقائياً النسخ المتطابقة
      // التي تختلف إجاباتها بصيغة بسيطة (مثل "كانبيرا"/"كانبرا" أو "1989"/"1989م")
      const key = qText;
      if (!key) return true;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  });

  return merged;
}

