// الثيمات: light (فاتح نظيف - الافتراضي) / dark (نحاسي داكن) / girls (وردي)
function applyTheme(theme) {
  State.theme = theme;
  let cls = '';
  if (theme === 'girls') cls = 'theme-girls';
  else if (theme === 'light') cls = 'theme-light';
  else cls = ''; // dark/boys
  // نحافظ على أي أصناف أخرى مثل css-fullscreen
  document.body.classList.remove('theme-girls', 'theme-light');
  if (cls) document.body.classList.add(cls);
  const btn = document.getElementById('theme-btn');
  if (btn) btn.textContent = theme === 'light' ? '☀️' : theme === 'girls' ? '🌸' : '🌙';
  try { localStorage.setItem('esalni_v6_theme', theme); } catch(e) {}
}

// التدوير: فاتح ← داكن ← وردي ← فاتح
function toggleTheme() {
  const order = ['light', 'dark', 'girls'];
  const cur = State.theme === 'boys' ? 'dark' : State.theme;
  const next = order[(order.indexOf(cur) + 1) % order.length];
  applyTheme(next);
  if (typeof showToast === 'function') {
    showToast(next === 'light' ? '☀️ الثيم الفاتح' : next === 'dark' ? '🌙 الثيم الداكن' : '🌸 الثيم الوردي');
  }
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function showToast(msg) {
  const old = document.querySelector('.toast');
  if (old) old.remove();
  const t = document.createElement('div');
  t.className = 'toast';
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2500);
}

// نظام صوتي محسّن - أصوات غنية بدل bip بسيط
let audioCtx = null;
function getAudioCtx() {
  if (!audioCtx) {
    try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); }
    catch(e) { return null; }
  }
  return audioCtx;
}

function playTone(freq, duration, vol = 0.15, type = 'sine', startDelay = 0) {
  const ctx = getAudioCtx();
  if (!ctx) return;
  const t = ctx.currentTime + startDelay;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t);
  gain.gain.setValueAtTime(0, t);
  gain.gain.linearRampToValueAtTime(vol, t + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.001, t + duration);
  osc.start(t);
  osc.stop(t + duration);
}

function playSound(type) {
  try {
    if (type === 'correct') {
      // صعود تدريجي (do-mi-sol-do) + harmony
      playTone(523, 0.15, 0.12, 'sine', 0);
      playTone(659, 0.15, 0.12, 'sine', 0.08);
      playTone(784, 0.2, 0.14, 'sine', 0.16);
      playTone(1047, 0.35, 0.16, 'sine', 0.24);
      // harmony أعلى
      playTone(1568, 0.3, 0.08, 'triangle', 0.26);
    } else if (type === 'wrong') {
      // نزول حزين
      playTone(330, 0.15, 0.14, 'sawtooth', 0);
      playTone(247, 0.25, 0.14, 'sawtooth', 0.12);
      playTone(165, 0.35, 0.12, 'sawtooth', 0.22);
    } else if (type === 'tick') {
      // tick قصير حاد
      playTone(880, 0.05, 0.08, 'square', 0);
    } else if (type === 'click') {
      // click خفيف ناعم
      playTone(800, 0.04, 0.06, 'sine', 0);
    } else if (type === 'win') {
      // نصر ملحمي
      playTone(523, 0.15, 0.15, 'triangle', 0);
      playTone(659, 0.15, 0.15, 'triangle', 0.1);
      playTone(784, 0.15, 0.15, 'triangle', 0.2);
      playTone(1047, 0.4, 0.18, 'triangle', 0.3);
      playTone(1319, 0.5, 0.15, 'sine', 0.4);
      playTone(1568, 0.6, 0.12, 'sine', 0.5);
    } else if (type === 'countTick') {
      // tick لعدّ النقاط
      playTone(1200, 0.03, 0.05, 'sine', 0);
    } else if (type === 'select') {
      // اختيار خانة
      playTone(660, 0.08, 0.1, 'triangle', 0);
      playTone(880, 0.12, 0.08, 'triangle', 0.05);
    } else if (type === 'lifeline') {
      // استخدام وسيلة مساعدة
      playTone(440, 0.08, 0.1, 'triangle', 0);
      playTone(660, 0.08, 0.1, 'triangle', 0.08);
      playTone(880, 0.15, 0.12, 'sine', 0.16);
    } else if (type === 'timeout') {
      // انتهاء الوقت
      playTone(200, 0.4, 0.18, 'sawtooth', 0);
      playTone(150, 0.5, 0.18, 'sawtooth', 0.2);
    }
  } catch(e) {}
}

function showConfetti() {
  const colors = State.theme === 'girls'
    ? ['#e8a4c9','#c2185b','#f0a5c4','#e63870','#b86b94']
    : ['#cd7f32','#cc5500','#d97e1f','#e89e54','#daa520'];
  for (let i = 0; i < 60; i++) {
    const el = document.createElement('div');
    el.className = 'confetti';
    el.style.left = Math.random() * 100 + 'vw';
    el.style.background = colors[Math.floor(Math.random() * colors.length)];
    el.style.animationDelay = Math.random() * 0.5 + 's';
    el.style.animationDuration = (2 + Math.random() * 2) + 's';
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 4000);
  }
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text || '';
  return div.innerHTML;
}

function toggleFullscreen() {
  const app = document.getElementById('app');
  const hasNativeFS = document.fullscreenElement || document.webkitFullscreenElement;
  const supportsFS = document.documentElement.requestFullscreen || document.documentElement.webkitRequestFullscreen;

  // إذا المتصفح يدعم Fullscreen API (أندرويد/ديسктوب) - نستخدمه
  if (supportsFS) {
    if (!hasNativeFS) {
      const el = document.documentElement;
      const req = el.requestFullscreen || el.webkitRequestFullscreen;
      req.call(el).catch(() => toggleCssFullscreen());
    } else {
      const exit = document.exitFullscreen || document.webkitExitFullscreen;
      if (exit) exit.call(document);
    }
  } else {
    // iOS Safari لا يدعم API - نستخدم وضع CSS احتياطي
    toggleCssFullscreen();
  }
}

// وضع ملء الشاشة عبر CSS - يعمل على كل الأجهزة بما فيها iPhone
function toggleCssFullscreen() {
  const app = document.getElementById('app');
  const fsBtn = document.getElementById('fs-btn');
  const isOn = document.body.classList.toggle('css-fullscreen');
  if (app) app.classList.toggle('fullscreen-mode', isOn);
  if (fsBtn) fsBtn.textContent = isOn ? '⊠' : '⛶';
  // تلميح للمستخدم على iPhone لإخفاء شريط المتصفح
  if (isOn && /iPhone|iPad|iPod/.test(navigator.userAgent)) {
    showToast('للتكبير الكامل: أضف الموقع للشاشة الرئيسية');
    window.scrollTo(0, 1);
  }
}

document.addEventListener('fullscreenchange', () => {
  const app = document.getElementById('app');
  const fsBtn = document.getElementById('fs-btn');
  if (document.fullscreenElement) {
    if (app) app.classList.add('fullscreen-mode');
    if (fsBtn) fsBtn.textContent = '⊠';
  } else {
    if (app) app.classList.remove('fullscreen-mode');
    if (fsBtn) fsBtn.textContent = '⛶';
  }
});

// ============================================================
// Navigation
// ============================================================
function navigate(screen) {
  if (State.timerInterval) { clearInterval(State.timerInterval); State.timerInterval = null; }
  State.screen = screen;
  render();
  if (typeof window.scrollTo === 'function') window.scrollTo(0, 0);
}

// التنقل من شريط الأسفل
function navFromBar(screen) {
  if (typeof playSound === 'function') playSound('click');
  navigate(screen);
}

// الشاشات التي يظهر فيها شريط التنقل السفلي
const BOTTOM_NAV_SCREENS = ['hub', 'home', 'profile', 'stats', 'admin', 'about'];
// خريطة الشاشة → عنصر التنقل النشط
const NAV_ACTIVE_MAP = { hub: 'hub', home: 'hub', profile: 'profile', stats: 'stats', admin: 'admin', about: 'hub' };

// يضبط ظهور شريط التنقل والأزرار العلوية حسب الشاشة الحالية
function updateChrome() {
  const screen = State.screen;
  // زر الإيقاف يظهر فقط أثناء اللعب
  const pauseBtn = document.getElementById('pause-btn');
  if (pauseBtn && pauseBtn.style) pauseBtn.style.display = (screen === 'play') ? 'flex' : 'none';
  // الأزرار العلوية: نخفيها أثناء اللعب الفعلي لتقليل التشتيت
  const topControls = document.getElementById('top-controls');
  if (topControls && topControls.style) {
    const hideTop = (screen === 'play' || screen === 'ready');
    topControls.style.display = hideTop ? 'none' : 'flex';
  }
  // شريط التنقل السفلي
  const nav = document.getElementById('bottom-nav');
  if (nav) {
    const show = BOTTOM_NAV_SCREENS.includes(screen);
    nav.classList.toggle('show', show);
    document.body.classList.toggle('has-bottom-nav', show);
    const active = NAV_ACTIVE_MAP[screen];
    nav.querySelectorAll('.bottom-nav-item').forEach(item => {
      item.classList.toggle('active', item.getAttribute('data-nav') === active);
    });
  }
}

function render() {
  const container = document.getElementById('screen-container');
  if (!container) return;
  let html = '';
  if (State.screen === 'theme-select') html = renderThemeSelect();
  else if (State.screen === 'onboarding') html = renderOnboarding();
  else if (State.screen === 'hub') html = renderHub();
  else if (State.screen === 'home') html = renderHome();
  else if (State.screen === 'setup') html = renderSetup();
  else if (State.screen === 'grid') html = renderGrid();
  else if (State.screen === 'ready') html = renderReady();
  else if (State.screen === 'play') html = renderPlay();
  else if (State.screen === 'summary') html = renderSummary();
  else if (State.screen === 'admin') html = renderAdmin();
  else if (State.screen === 'about') html = renderAbout();
  else if (State.screen === 'stats') html = renderStats();
  else if (State.screen === 'profile') html = renderProfile();
  else if (State.screen === 'spy') html = (typeof renderSpy === 'function' ? renderSpy() : '');
  else if (State.screen === 'most') html = (typeof renderMost === 'function' ? renderMost() : '');
  container.innerHTML = html;
  if (typeof updateChrome === 'function') updateChrome();
  if (State.screen === 'play' && State.game && State.game.currentQuestion) startTimerIfNeeded();
}

