// ============================================================
// نظام تتبّع الأسئلة المطروحة — يمنع تكرار نفس الأسئلة عند إعادة اللعب
// يُخزَّن محلياً على الجهاز ويُعاد تدويره تلقائياً عند نفاد الأسئلة الجديدة
// ============================================================
function qKey(q) {
  return (q && q.q ? q.q : '').trim()
    .replace(/[«»"'""'']/g, '')
    .replace(/[؟?\.\،,]/g, '')
    .replace(/\s+/g, ' ')
    .trim().toLowerCase();
}
let SeenQuestions = {};
function loadSeen() {
  try { SeenQuestions = JSON.parse(localStorage.getItem('esalni_v6_seen_q') || '{}') || {}; }
  catch (e) { SeenQuestions = {}; }
}
function saveSeen() {
  try { localStorage.setItem('esalni_v6_seen_q', JSON.stringify(SeenQuestions)); } catch (e) {}
}
function isSeen(catId, q) {
  return !!(SeenQuestions[catId] && SeenQuestions[catId][qKey(q)]);
}
function markSeen(catId, q) {
  if (!catId || !q) return;
  if (!SeenQuestions[catId]) SeenQuestions[catId] = {};
  SeenQuestions[catId][qKey(q)] = 1;
  saveSeen();
}
function getCoverage(catId) {
  const total = (State.questionsDB[catId] || []).length;
  const seen = SeenQuestions[catId] ? Object.keys(SeenQuestions[catId]).length : 0;
  const capped = Math.min(seen, total);
  return { total, seen: capped, fresh: Math.max(0, total - capped), pct: total ? Math.round(capped / total * 100) : 0 };
}
function resetSeen(catId) {
  if (catId) delete SeenQuestions[catId];
  else SeenQuestions = {};
  saveSeen();
}
// يرتّب القائمة بحيث تأتي الأسئلة غير المطروحة أولاً ثم المطروحة (للتدوير)
function freshFirst(catId, arr) {
  const unseen = shuffle(arr.filter(q => !isSeen(catId, q)));
  const seen = shuffle(arr.filter(q => isSeen(catId, q)));
  return unseen.concat(seen);
}

function startGame() {
  if (State.setup.categories.length !== 6) {
    showToast('اختر 6 فئات بالضبط');
    return;
  }

  // بناء الشبكة: لكل فئة 6 أسئلة بتدرّج صعوبة حقيقي من 100 (سهل) إلى 600 (خبير)
  const grid = {};
  State.setup.categories.forEach(catId => {
    const allQuestions = State.questionsDB[catId] || [];

    // إعادة تدوير تلقائية: إذا تبقّى أقل من 6 أسئلة جديدة في الفئة، نصفّر سجلّها لتبدأ جولة جديدة
    const cov = getCoverage(catId);
    if (cov.total > 6 && cov.fresh < 6) resetSeen(catId);

    // نصنّف الأسئلة حسب صعوبتها الفعلية، مع تقديم غير المطروحة سابقاً (منع التكرار)
    const pools = {
      easy:   freshFirst(catId, allQuestions.filter(q => (q.pts || 200) <= 100)),  // سهل
      medium: freshFirst(catId, allQuestions.filter(q => (q.pts || 200) === 200)), // متوسط
      hard:   freshFirst(catId, allQuestions.filter(q => (q.pts || 200) === 400)), // صعب
      expert: freshFirst(catId, allQuestions.filter(q => (q.pts || 200) >= 500)),  // خبير (500-600)
    };

    // خريطة كل صف لمصدر الصعوبة المناسب (تدرّج حقيقي)
    // منحنى صعوبة مرفوع: الصف 0=100 سهل، 1=200 متوسط، 2=300 صعب، 3=400 صعب، 4=500 خبير، 5=600 خبير
    const rowPlan = ['easy', 'medium', 'hard', 'hard', 'expert', 'expert'];
    const usedQ = new Set();
    const selected = [];

    const pullFrom = (poolName) => {
      const pool = pools[poolName];
      while (pool.length) {
        const q = pool.shift();
        if (!usedQ.has(q.q)) { usedQ.add(q.q); return q; }
      }
      return null;
    };
    // ترتيب احتياطي للسحب إذا نفد مستوى معيّن
    const fallbackOrder = ['hard', 'expert', 'medium', 'easy'];

    rowPlan.forEach(level => {
      let q = pullFrom(level);
      if (!q) { // المستوى نفد - نسحب من الأقرب المتاح
        for (const fb of fallbackOrder) { q = pullFrom(fb); if (q) break; }
      }
      if (!q) { // احتياط أخير: أي سؤال غير مستخدم
        const any = allQuestions.find(x => !usedQ.has(x.q));
        if (any) { usedQ.add(any.q); q = any; }
      }
      if (q) selected.push(q);
    });

    // ترتيب: المؤشر 0 = 100 نقطة، المؤشر 5 = 600 نقطة
    grid[catId] = selected.slice(0, 6).map((q, i) => ({
      ...q,
      gridPoints: POINT_LEVELS[i],
      used: false,
    }));
  });

  State.game = {
    grid, // {catId: [{question, gridPoints, used}, ...]}
    categories: [...State.setup.categories],
    currentTeam: 0,
    teams: State.setup.teams.map(t => ({
      ...t,
      score: 0,
      streak: 0,        // سلسلة الإجابات الصحيحة المتتالية
      bestStreak: 0,    // أطول سلسلة حققها الفريق
      lifelines: { fifty: true, double: true, skip: true }, // 3 وسائل لكل فريق
    })),
    timePerQuestion: State.setup.timePerQuestion,
    currentQuestion: null,
    currentCat: null,
    currentLevel: null,
    timeLeft: 0,
    selectedAnswer: null,
    showAnswer: false,
    showHint: false,
    eliminatedAnswers: [],
    doubleActive: false,
    history: [],
    startTime: Date.now(),
  };
  saveLastSetup();
  clearGameProgress();
  saveGameProgress();
  navigate('grid');
}

// ============================================================
// شاشة الشبكة 6×6 - النظام الأساسي الجديد!
// ============================================================
function renderGrid() {
  const g = State.game;
  if (!g) return '';

  // عرض الشبكة 6 أعمدة (فئة لكل عمود) × 6 صفوف (مستوى نقاط)
  // الصف 0 = 100 نقطة، الصف 5 = 600 نقطة
  const headersHtml = g.categories.map(catId => {
    const cat = CATEGORIES.find(c => c.id === catId);
    return `
      <div class="grid-header-cell" style="color:${cat.color}">
        <div class="grid-header-icon">${getCategoryIcon(cat.id, 28, cat.color)}</div>
        <span>${cat.name.replace('وعواصم', '').replace('وقارات', '').replace('وتلفزيون', '').replace('والأكل', '').trim()}</span>
      </div>
    `;
  }).join('');

  // الشبكة من الأعلى (100) إلى الأسفل (600)
  let cellsHtml = '';
  for (let row = 0; row < 6; row++) {
    g.categories.forEach(catId => {
      const cell = g.grid[catId][row];
      const points = POINT_LEVELS[row];
      cellsHtml += `
        <div class="grid-cell ${cell.used ? 'used' : ''}"
             onclick="${cell.used ? '' : `selectCell('${catId}', ${row})`}">
          ${points}
        </div>
      `;
    });
  }

  const currentTeam = g.teams[g.currentTeam];
  const remaining = g.categories.reduce((sum, c) => sum + g.grid[c].filter(q => !q.used).length, 0);

  return `
    <div class="screen">
      <div class="game-topbar">
        <button class="btn-home-exit" onclick="confirmExitGame()" title="الرئيسية">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><path d="M9 22V12h6v10"/></svg>
        </button>
        <div class="round-indicator">باقي ${remaining} سؤال</div>
        <div style="width:42px"></div>
      </div>

      <div class="play-cat" style="text-align:center;margin-bottom:12px">دور ${currentTeam.avatar} ${escapeHtml(currentTeam.name)}</div>

      <div class="game-progress">
        <div class="game-progress-bar">
          <div class="game-progress-fill" style="width:${((36 - remaining) / 36) * 100}%"></div>
        </div>
        <div class="game-progress-text">${36 - remaining} / 36 سؤال</div>
      </div>

      ${renderTeamsRow()}

      <div class="warning-banner" style="background:linear-gradient(135deg,rgba(205,127,50,0.2),rgba(205,127,50,0.05));border-color:var(--border-warm);color:var(--bronze-light)">
        <span>💡</span>
        <div>اضغط على أي خانة لاختيار سؤال. كلما زادت النقاط، زادت الصعوبة.</div>
      </div>

      <div class="grid-game">
        ${headersHtml}
        ${cellsHtml}
      </div>

      ${remaining === 0 ? `
        <button class="btn btn-primary btn-full" onclick="navigate('summary')" style="padding:18px;font-size:18px;margin-top:20px">
          🏆 عرض النتائج النهائية
        </button>
      ` : ''}
    </div>
  `;
}

function selectCell(catId, level) {
  const g = State.game;
  const cell = g.grid[catId][level];
  if (cell.used) return;

  playSound('select');
  g.currentCat = catId;
  g.currentLevel = level;
  g.currentQuestion = { ...cell, shuffledAnswers: shuffle([cell.a, ...cell.wrong]) };
  markSeen(catId, cell); // سجّل أن هذا السؤال طُرح حتى لا يتكرر في الجولات القادمة
  g.timeLeft = g.timePerQuestion;
  g.selectedAnswer = null;
  g.showAnswer = false;
  g.showHint = false;
  g.eliminatedAnswers = [];
  g.doubleActive = false;
  // عرض شاشة "استعداد الفريق" أولاً لمنع رؤية السؤال بالخطأ
  navigate('ready');
}

// ============================================================
// شاشة "استعداد الفريق" - تمنع رؤية السؤال قبل بدء الدور
