// ============================================================
// نظام الصور البصرية فوق الأسئلة
// أعلام حقيقية بحجم كبير للفئة البصرية، ورسوم/رموز معبّرة سياقية للباقي
// يعمل بالكامل دون إنترنت
// ============================================================
const CAT_VISUAL_EMOJI = {
  cities:'🏙️', flags:'🚩', geo:'🌍', history:'🏛️', sport:'🏆', cinema:'🎬',
  music:'🎵', tech:'💻', science:'🔬', food:'🍽️', literature:'📚', animals:'🦁',
  celebs:'⭐', arabia:'🕌', mystery:'🧩', general:'💡'
};
const KEYWORD_VISUAL = [
  [/علم|أعلام/, '🚩'], [/عاصم|مدين|مدن/, '🏙️'], [/جبل|قمّ|قمة|إفرست|هضب/, '⛰️'],
  [/نهر|بحر|محيط|خليج|بحير/, '🌊'], [/صحراء|رمل/, '🏜️'], [/جزير/, '🏝️'], [/بركان/, '🌋'],
  [/كرة القدم|هدّاف|هداف|مونديال|كأس العالم|دوري|نادي|منتخب/, '⚽'], [/تنس/, '🎾'],
  [/سلّ|سلة/, '🏀'], [/أولمب|ميدالي|بطول/, '🏅'], [/سباق|فورمولا|سيارة/, '🏎️'], [/ملاكم/, '🥊'],
  [/فيلم|سينما|مخرج|أوسكار|ممثل|بطولة الفيلم/, '🎬'], [/مسلسل|تلفز/, '📺'],
  [/أغني|موسيق|مغنّ|مغني|أوبرا|بيانو|آلة|لحن|سلّم موسيقي|عود/, '🎵'],
  [/كتاب|رواي|شاعر|أدب|ديوان|قصيد|مؤلف/, '📖'],
  [/حاسوب|إنترنت|تطبيق|هاتف|برمج|ذكاء اصطناعي|شركة تقني|موقع/, '💻'],
  [/كوكب|فضاء|نجم|مجرّ|مجرة|قمر|مذنّب|فلك/, '🪐'], [/ذرّ|كيمياء|عنصر|تفاعل|جزيء/, '⚗️'],
  [/جسم|دم|قلب|دماغ|خلي|عظم|عضو/, '🫀'], [/كهرباء|طاقة|فيزياء/, '⚡'],
  [/طبخ|طعام|أكل|توابل|فاكه|مطبخ|طبق|حلو|جبن|فطر/, '🍽️'],
  [/قط|كلب|أسد|نمر|فيل|طائر|حيوان|سمك|حوت|زواحف|ثديي|حشر/, '🐾'],
  [/ملك|أمير|سلطان|خليف|حرب|معرك|عثمان|إمبراطور|ثور/, '⚔️'],
  [/مسجد|كعب|قرآن|نبي|صحاب|إسلام|صلا|حج|رمضان/, '🕌'],
  [/لغز|رقم|عدد|حساب|رياضيات|معادل/, '🧩'], [/رائد فضاء|نوبل|عالم|اختراع/, '🏆']
];
function pickQuestionEmoji(q, catId) {
  if (q.img && /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{1F1E6}-\u{1F1FF}]/u.test(q.img)) return q.img;
  const text = (q.q || '') + ' ' + (q.a || '');
  for (const [re, em] of KEYWORD_VISUAL) { if (re.test(text)) return em; }
  return CAT_VISUAL_EMOJI[catId] || '❓';
}
function getQuestionVisual(q, catId) {
  const cat = CATEGORIES.find(c => c.id === catId) || { color: '#d68a3c', name: '' };
  const emoji = pickQuestionEmoji(q, catId);
  const isFlag = catId === 'flags';
  return `
    <div class="q-visual ${isFlag ? 'q-visual-flag' : ''}" style="--qv:${cat.color}">
      <div class="q-visual-shine"></div>
      <div class="q-visual-art">${emoji}</div>
      <div class="q-visual-tag">${escapeHtml(cat.name)}</div>
    </div>
  `;
}

function renderPlay() {
  const g = State.game;
  const q = g.currentQuestion;
  if (!q) return '';
  const cat = CATEGORIES.find(c => c.id === g.currentCat);
  const radius = 45;
  const circumference = 2 * Math.PI * radius;
  const progress = (g.timeLeft / g.timePerQuestion) * circumference;
  const timerClass = g.timeLeft <= 5 ? 'danger' : g.timeLeft <= 15 ? 'warning' : '';
  const points = q.gridPoints;
  const actualPoints = g.doubleActive ? points * 2 : points;

  const answersHtml = q.shuffledAnswers.map((ans, idx) => {
    let cls = 'answer-btn';
    if (g.eliminatedAnswers.includes(ans)) cls += ' eliminated';
    if (g.showAnswer) {
      if (ans === q.a) cls += ' correct';
      else if (ans === g.selectedAnswer) cls += ' wrong';
      else cls += ' disabled';
    }
    let prefix = '';
    if (g.showAnswer && ans === q.a) prefix = '✓ ';
    else if (g.showAnswer && ans === g.selectedAnswer) prefix = '✗ ';
    return `<button class="${cls}" onclick="answerByIdx(${idx})">${prefix}${escapeHtml(ans)}</button>`;
  }).join('');

  const currentTeam = g.teams[g.currentTeam];
  const ll = currentTeam.lifelines;

  return `
    <div class="screen">
      <div class="play-header">
        <span class="badge badge-warm">
          ${actualPoints} نقطة ${g.doubleActive ? '⚡' : ''}
        </span>
        <div class="play-cat" style="display:flex;align-items:center;gap:8px">
          <span style="display:inline-flex;color:${cat.color}">${getCategoryIcon(cat.id, 22, cat.color)}</span>
          ${cat.name}
        </div>
      </div>

      ${renderTeamsRow()}

      <div class="play-layout">
        <div class="play-left">
          <div class="timer-container">
            <div class="timer-circle">
              <svg viewBox="0 0 100 100">
                <circle class="timer-bg" cx="50" cy="50" r="${radius}"/>
                <circle class="timer-fg ${timerClass}" cx="50" cy="50" r="${radius}"
                  stroke-dasharray="${circumference}" stroke-dashoffset="${circumference - progress}"/>
              </svg>
              <div class="timer-number">${g.timeLeft}</div>
            </div>
          </div>

          ${getQuestionVisual(q, g.currentCat)}

          <div class="question-text">${escapeHtml(q.q)}</div>

          ${g.showHint && q.hint ? `<div class="hint-card">💡 ${escapeHtml(q.hint)}</div>` : ''}
        </div>

        <div class="play-right">
          ${!g.showAnswer ? `
            <div class="lifelines-bar">
              <button class="lifeline-btn ${!ll.fifty ? 'used' : ''}" onclick="useLifeline('fifty')" ${!ll.fifty ? 'disabled' : ''}>
                ✂️ 50:50
              </button>
              <button class="lifeline-btn ${!ll.double || g.doubleActive ? 'used' : ''}" onclick="useLifeline('double')" ${!ll.double || g.doubleActive ? 'disabled' : ''}>
                ⚡ ×2
              </button>
              <button class="lifeline-btn ${!ll.skip ? 'used' : ''}" onclick="useLifeline('skip')" ${!ll.skip ? 'disabled' : ''}>
                ⏭️ تخطي
              </button>
            </div>
          ` : ''}

          <div class="answers-grid">${answersHtml}</div>

          ${!g.showAnswer && !g.showHint && q.hint ? `
            <button class="btn btn-ghost btn-sm btn-full" onclick="State.game.showHint=true;render()" style="margin-top:8px">
              💡 إظهار تلميح
            </button>
          ` : ''}
        </div>
      </div>
    </div>
  `;
}

// استخدام وسيلة مساعدة
function useLifeline(type) {
  const g = State.game;
  const team = g.teams[g.currentTeam];
  if (!team.lifelines[type]) return;

  playSound('lifeline');
  Stats.lifelinesUsed = (Stats.lifelinesUsed || 0) + 1;
  // علم اللعبة كاستخدمت وسائل
  if (!g.usedLifelinesInGame) g.usedLifelinesInGame = true;

  if (type === 'fifty') {
    // حذف إجابتين خاطئتين
    const q = g.currentQuestion;
    const wrongs = q.shuffledAnswers.filter(a => a !== q.a);
    const toEliminate = shuffle(wrongs).slice(0, 2);
    g.eliminatedAnswers = toEliminate;
    team.lifelines.fifty = false;
    showToast('✂️ تم حذف إجابتين خاطئتين');
  } else if (type === 'double') {
    g.doubleActive = true;
    team.lifelines.double = false;
    showToast('⚡ النقاط مضاعفة!');
  } else if (type === 'skip') {
    team.lifelines.skip = false;
    if (State.timerInterval) { clearInterval(State.timerInterval); State.timerInterval = null; }
    // خصم 25% من نقاط السؤال (التخطي ليس مجاني تماماً للتوازن)
    const penalty = Math.floor(g.currentQuestion.gridPoints * 0.25);
    team.score = Math.max(0, team.score - penalty);
    // الخانة تُعتبر مستخدمة (لا تظل متاحة)
    g.grid[g.currentCat][g.currentLevel].used = true;
    showToast(`⏭️ تم التخطي (-${penalty} نقطة)`);
    nextTurn();
    return;
  }
  render();
}

function answerByIdx(idx) {
  const g = State.game;
  const ans = g.currentQuestion.shuffledAnswers[idx];
  if (g.selectedAnswer || g.showAnswer) return;
  if (g.eliminatedAnswers.includes(ans)) return;
  if (State.timerInterval) { clearInterval(State.timerInterval); State.timerInterval = null; }

  g.selectedAnswer = ans;
  g.showAnswer = true;
  const isCorrect = ans === g.currentQuestion.a;
  const basePoints = g.currentQuestion.gridPoints * (g.doubleActive ? 2 : 1);
  const team = g.teams[g.currentTeam];

  // علّم الخانة كمستخدمة
  g.grid[g.currentCat][g.currentLevel].used = true;

  if (isCorrect) {
    playSound('correct');
    showConfetti();
    if (navigator.vibrate) { try { navigator.vibrate(50); } catch(e) {} }

    // ===== نظام المكافآت المحفّز =====
    // 1) مكافأة السرعة: كلما بقي وقت أكثر، زادت المكافأة (حتى 30% من نقاط السؤال)
    const timeRatio = g.timePerQuestion ? Math.max(0, g.timeLeft / g.timePerQuestion) : 0;
    const speedBonus = Math.round(g.currentQuestion.gridPoints * 0.3 * timeRatio);

    // 2) مكافأة السلسلة: كل إجابة صحيحة متتالية ترفع المضاعف (سقف عند ×5)
    team.streak = (team.streak || 0) + 1;
    if (team.streak > (team.bestStreak || 0)) team.bestStreak = team.streak;
    const streakBonus = team.streak >= 2 ? Math.min(team.streak - 1, 4) * 50 : 0;

    const totalGain = basePoints + speedBonus + streakBonus;
    team.score += totalGain;
    Stats.correctAnswers = (Stats.correctAnswers || 0) + 1;
    if (g.currentQuestion.gridPoints === 600) {
      Stats.hardAnswered = (Stats.hardAnswered || 0) + 1;
    }

    // رسالة المكافأة
    let bonusMsg = '';
    if (team.streak >= 2) bonusMsg += `🔥 سلسلة ×${team.streak}! `;
    if (speedBonus > 0) bonusMsg += `⚡ +${speedBonus} سرعة `;
    if (streakBonus > 0) bonusMsg += `🎯 +${streakBonus} مكافأة`;
    if (bonusMsg) showToast(bonusMsg.trim());

    // مكافأة المعلومة للعرض
    g.lastGain = { base: basePoints, speed: speedBonus, streak: streakBonus, total: totalGain };
  } else {
    playSound('wrong');
    if (navigator.vibrate) { try { navigator.vibrate([60, 40, 60]); } catch(e) {} }
    Stats.wrongAnswers = (Stats.wrongAnswers || 0) + 1;
    team.streak = 0; // كسر السلسلة
    g.lastGain = null;
  }
  const points = basePoints;
  // تتبع الفئات المُلعبة
  if (!Stats.categoriesPlayed) Stats.categoriesPlayed = {};
  Stats.categoriesPlayed[g.currentCat] = (Stats.categoriesPlayed[g.currentCat] || 0) + 1;
  saveStats();

  g.history.push({
    cat: g.currentCat,
    points,
    correct: isCorrect,
    team: g.currentTeam,
  });

  render();
  setTimeout(() => nextTurn(), 2000);
}

function nextTurn() {
  const g = State.game;
  g.currentTeam = (g.currentTeam + 1) % g.teams.length;
  g.currentQuestion = null;
  g.selectedAnswer = null;
  g.showAnswer = false;
  g.showHint = false;
  g.eliminatedAnswers = [];
  g.doubleActive = false;

  // هل انتهت اللعبة؟
  const remaining = g.categories.reduce((sum, c) => sum + g.grid[c].filter(q => !q.used).length, 0);
  if (remaining === 0) {
    clearGameProgress();
    navigate('summary');
  } else {
    saveGameProgress();
    navigate('grid');
  }
}

// pause menu
function pauseGameMenu() {
  if (State.timerInterval) { clearInterval(State.timerInterval); State.timerInterval = null; }
  const modal = document.createElement('div');
  modal.className = 'modal-overlay';
  modal.id = 'pause-modal';
  modal.innerHTML = `
    <div class="modal-content" onclick="event.stopPropagation()" style="max-width:380px">
      <h3 class="title-md" style="text-align:center;margin-bottom:8px">⏸️ توقف مؤقت</h3>
      <p style="text-align:center;color:var(--text-dim);font-size:13px;margin-bottom:22px">تقدمك محفوظ تلقائياً</p>
      <button class="btn btn-primary btn-full" onclick="closePauseModal();continueGame()" style="margin-bottom:10px;padding:16px">
        ▶️ متابعة اللعب
      </button>
      <button class="btn btn-secondary btn-full" onclick="closePauseModal();navigate('summary')" style="margin-bottom:10px;padding:14px">
        🏁 إنهاء وعرض النتائج
      </button>
      <button class="btn btn-secondary btn-full" onclick="confirmExitToHome()" style="padding:14px;margin-bottom:10px">
        🏠 الخروج (مع حفظ التقدم)
      </button>
      <button class="btn btn-danger btn-full" onclick="abandonGame()" style="padding:14px">
        🗑️ حذف اللعبة الحالية
      </button>
    </div>
  `;
  modal.onclick = closePauseModal;
  document.body.appendChild(modal);
}

function closePauseModal() {
  const m = document.getElementById('pause-modal');
  if (m) m.remove();
}

function continueGame() {
  if (State.game && State.game.currentQuestion) startTimerIfNeeded();
}

function confirmExitToHome() {
  if (confirm('سيتم حفظ التقدم تلقائياً. هل تريد الخروج؟')) {
    closePauseModal();
    saveGameProgress();
    State.game = null;
    navigate('home');
  }
}

// زر الرجوع للرئيسية من شاشة الشبكة (يحفظ التقدم)
function confirmExitGame() {
  playSound('click');
  if (confirm('سيتم حفظ تقدم اللعبة. هل تريد الرجوع للرئيسية؟')) {
    saveGameProgress();
    State.game = null;
    navigate('home');
  }
}

function abandonGame() {
  if (confirm('متأكد؟ سيتم حذف اللعبة الحالية نهائياً.')) {
    closePauseModal();
    clearGameProgress();
    State.game = null;
    navigate('home');
  }
}

// المؤقت
function startTimerIfNeeded() {
  const g = State.game;
  if (!g || !g.currentQuestion) return;
  if (g.showAnswer) return;
  if (State.timerInterval) return;
  State.timerInterval = setInterval(() => {
    g.timeLeft--;
    if (g.timeLeft <= 6 && g.timeLeft > 0) {
      playSound('tick');
      // اهتزاز خفيف في آخر 5 ثواني (للأجهزة الداعمة)
      if (g.timeLeft <= 5 && navigator.vibrate) {
        try { navigator.vibrate(80); } catch(e) {}
      }
    }
    if (g.timeLeft <= 0) {
      clearInterval(State.timerInterval);
      State.timerInterval = null;
      g.showAnswer = true;
      playSound('timeout');
      // اهتزاز أطول عند انتهاء الوقت
      if (navigator.vibrate) { try { navigator.vibrate([100, 50, 100]); } catch(e) {} }
      if (g.teams && g.teams[g.currentTeam]) g.teams[g.currentTeam].streak = 0; // كسر السلسلة عند انتهاء الوقت
      g.grid[g.currentCat][g.currentLevel].used = true;
      render();
      setTimeout(() => nextTurn(), 2000);
      return;
    }
    const timerEl = document.querySelector('.timer-number');
    const timerFg = document.querySelector('.timer-fg');
    if (timerEl) timerEl.textContent = g.timeLeft;
    if (timerFg) {
      const circ = 2 * Math.PI * 45;
      timerFg.setAttribute('stroke-dashoffset', circ - (g.timeLeft / g.timePerQuestion) * circ);
      if (g.timeLeft <= 5) { timerFg.classList.remove('warning'); timerFg.classList.add('danger'); }
      else if (g.timeLeft <= 15) timerFg.classList.add('warning');
    }
  }, 1000);
}

// ============================================================
// Summary
// ============================================================
function renderSummary() {
  const g = State.game;
  if (!g) { navigate('home'); return ''; }
  const sorted = [...g.teams].sort((a, b) => b.score - a.score);
  const winner = sorted[0];
  const isTie = sorted.length > 1 && sorted[0].score === sorted[1].score;
  let xpEarned = 0;

  if (g.startTime && !g.saved) {
    g.saved = true;

    // ===== منح XP وتحديث الإحصائيات =====
    Stats.totalGames = (Stats.totalGames || 0) + 1;
    xpEarned += 30; // 30 XP لإكمال لعبة

    // إجمالي النقاط من اللعبة
    const totalGameScore = g.teams.reduce((s, t) => s + t.score, 0);
    Stats.totalScore = (Stats.totalScore || 0) + totalGameScore;

    if (!isTie) {
      Stats.wins = (Stats.wins || 0) + 1;
      xpEarned += 50; // 50 XP إضافية للفوز
      Stats.currentStreak = (Stats.currentStreak || 0) + 1;
      if (Stats.currentStreak > (Stats.bestStreak || 0)) {
        Stats.bestStreak = Stats.currentStreak;
      }
      // فوز بدون وسائل مساعدة
      if (!g.usedLifelinesInGame) {
        Stats.winNoLifelines = (Stats.winNoLifelines || 0) + 1;
        xpEarned += 50; // مكافأة إضافية
      }
    } else {
      // التعادل لا يكسر السلسلة
    }

    // فحص "أجاب كل أسئلة فئة بدون خطأ" (يحتاج 6 إجابات صحيحة من فئة)
    const perfectCats = {};
    g.history.forEach(h => {
      if (!perfectCats[h.cat]) perfectCats[h.cat] = { correct: 0, total: 0 };
      perfectCats[h.cat].total++;
      if (h.correct) perfectCats[h.cat].correct++;
    });
    Object.values(perfectCats).forEach(c => {
      if (c.total === 6 && c.correct === 6) {
        Stats.perfectCategories = (Stats.perfectCategories || 0) + 1;
      }
    });

    addXP(xpEarned);
    saveStats();
    setTimeout(() => checkAchievements(), 1500);

    State.gameHistory.unshift({
      date: new Date().toISOString(),
      teams: sorted.map(t => ({ name: t.name, avatar: t.avatar, score: t.score })),
      winner: isTie ? 'تعادل' : winner.name,
      xpEarned,
    });
    if (State.gameHistory.length > 20) State.gameHistory = State.gameHistory.slice(0, 20);
    try { localStorage.setItem('esalni_v6_history', JSON.stringify(State.gameHistory)); } catch(e) {}
    clearGameProgress();
  } else if (g.xpEarned) {
    xpEarned = g.xpEarned;
  }
  g.xpEarned = xpEarned;

  // confetti متتابع + صوت نصر
  setTimeout(() => {
    if (!isTie) {
      showConfetti();
      playSound('win');
      setTimeout(() => { showConfetti(); }, 600);
      setTimeout(() => { showConfetti(); }, 1200);
    }
  }, 300);

  // عدّ النقاط بطريقة مثيرة (count-up animation)
  setTimeout(() => animateScoreCounts(), 800);

  const currentLevel = getCurrentLevel();
  const progress = getLevelProgress();
  const nextLevel = getNextLevel();

  return `
    <div class="screen">
      <div style="text-align:center;padding:30px 0">
        <div style="font-size:110px;margin-bottom:14px" class="${!isTie ? 'summary-trophy' : ''}">${isTie ? '🤝' : '🏆'}</div>
        <h1 class="title-xl">${isTie ? 'تعادل!' : `فاز ${escapeHtml(winner.name)}`}</h1>
        ${!isTie ? `<div style="color:var(--bronze-light);font-size:24px;font-weight:700;margin-top:8px">${winner.avatar} <span id="winner-final-score" data-target="${winner.score}">0</span> نقطة</div>` : ''}
      </div>

      ${xpEarned > 0 ? `
        <div class="card xp-earned-card" style="margin-bottom:18px;padding:18px;background:linear-gradient(135deg,var(--bg-card-hover),var(--bg-card));border-color:${currentLevel.color}">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
            <div style="display:flex;align-items:center;gap:10px">
              <span style="font-size:30px">${currentLevel.icon}</span>
              <div>
                <div style="font-size:13px;color:var(--text-dim);font-weight:500">المستوى الحالي</div>
                <div style="font-weight:700;color:${currentLevel.color};font-size:16px">${currentLevel.name}</div>
              </div>
            </div>
            <div style="background:linear-gradient(135deg,var(--bronze-light),var(--bronze));color:#fff;padding:8px 16px;border-radius:14px;font-weight:700;font-size:16px">+${xpEarned} XP</div>
          </div>
          ${nextLevel ? `
            <div style="height:8px;background:var(--bg-deep);border-radius:4px;overflow:hidden;margin:6px 0">
              <div style="width:${progress}%;height:100%;background:linear-gradient(90deg,var(--bronze-light),var(--bronze));transition:width 1s;border-radius:4px"></div>
            </div>
            <div style="font-size:11px;color:var(--text-mute);text-align:center;font-weight:500">
              ${Stats.xp} / ${nextLevel.minXP} XP للمستوى التالي (${nextLevel.name})
            </div>
          ` : ''}
        </div>
      ` : ''}

      <div class="card" style="margin-bottom:22px">
        <h3 class="title-md" style="font-size:22px;margin-bottom:14px;text-align:center">الترتيب النهائي</h3>
        ${sorted.map((team, idx) => `
          <div class="summary-place" style="display:flex;align-items:center;padding:16px;background:${idx === 0 ? 'var(--bg-card-hover)' : 'transparent'};border-radius:14px;margin-bottom:8px;border:${idx === 0 ? '1.5px solid var(--bronze)' : '1px solid transparent'}">
            <div style="width:40px;height:40px;border-radius:50%;background:${idx === 0 ? 'linear-gradient(135deg, var(--bronze-light), var(--bronze))' : idx === 1 ? '#a8a29e' : '#a0522d'};color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;margin-left:14px;font-size:18px">${idx + 1}</div>
            <div style="font-size:32px;margin-left:14px">${team.avatar}</div>
            <div style="flex:1;font-weight:700;font-size:17px">${escapeHtml(team.name)}</div>
            <div class="summary-score-anim" style="font-size:30px" data-score-target="${team.score}">0</div>
          </div>
        `).join('')}
      </div>
      <button class="btn btn-share btn-full" onclick="openShareModal()" style="margin-bottom:10px;padding:18px;font-size:17px">
        📤 شارك النتيجة
      </button>
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        <button class="btn btn-primary" style="flex:1;min-width:140px" onclick="State.game=null;replayLastGame()">🔄 إعادة بنفس الإعداد</button>
        <button class="btn btn-secondary" style="flex:1;min-width:140px" onclick="State.game=null;navigate('setup')">🎮 لعب جديد</button>
      </div>
      <button class="btn btn-ghost btn-full" style="margin-top:10px" onclick="State.game=null;navigate('home')">🏠 الرئيسية</button>
    </div>
  `;
}

// ============================================================
// نظام مشاركة النتيجة - توليد صورة احترافية
// ============================================================
function generateResultImage() {
  const g = State.game;
  if (!g) return null;
  const sorted = [...g.teams].sort((a, b) => b.score - a.score);
  const winner = sorted[0];
  const isTie = sorted.length > 1 && sorted[0].score === sorted[1].score;
  const theme = State.theme === 'girls' ? 'girls' : 'boys';

  const canvas = document.createElement('canvas');
  // أبعاد مثلى لشير على واتساب (1080×1080 مربع)
  canvas.width = 1080;
  canvas.height = 1080;
  const ctx = canvas.getContext('2d');

  // === الخلفية: gradient أرجواني-نحاسي ===
  const bgGradient = ctx.createLinearGradient(0, 0, 1080, 1080);
  if (theme === 'girls') {
    bgGradient.addColorStop(0, '#2d0a36');
    bgGradient.addColorStop(0.5, '#4a1042');
    bgGradient.addColorStop(1, '#1a0420');
  } else {
    bgGradient.addColorStop(0, '#1a0033');
    bgGradient.addColorStop(0.5, '#2d0a4d');
    bgGradient.addColorStop(1, '#0d0024');
  }
  ctx.fillStyle = bgGradient;
  ctx.fillRect(0, 0, 1080, 1080);

  // === توهجات نحاسية في الخلفية ===
  const glow1 = ctx.createRadialGradient(200, 200, 0, 200, 200, 500);
  const accentColor = theme === 'girls' ? 'rgba(232,164,201,0.25)' : 'rgba(205,127,50,0.3)';
  glow1.addColorStop(0, accentColor);
  glow1.addColorStop(1, 'transparent');
  ctx.fillStyle = glow1;
  ctx.fillRect(0, 0, 1080, 1080);

  const glow2 = ctx.createRadialGradient(880, 880, 0, 880, 880, 500);
  const accent2 = theme === 'girls' ? 'rgba(194,24,91,0.2)' : 'rgba(204,85,0,0.22)';
  glow2.addColorStop(0, accent2);
  glow2.addColorStop(1, 'transparent');
  ctx.fillStyle = glow2;
  ctx.fillRect(0, 0, 1080, 1080);

  // === اللوغو 36 في الأعلى ===
  drawLogo36(ctx, 540, 180, 180);

  // === كلمة "36" تحت اللوغو ===
  ctx.fillStyle = '#e89e54';
  ctx.font = '900 90px Inter, "IBM Plex Sans Arabic", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('36', 540, 340);

  // tagline
  ctx.fillStyle = '#c9a878';
  ctx.font = '600 26px "IBM Plex Sans Arabic", sans-serif';
  ctx.fillText('شبكة 6×6 • سؤال × جواب', 540, 400);

  // === خط فاصل ===
  ctx.strokeStyle = 'rgba(205,127,50,0.4)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(280, 460);
  ctx.lineTo(800, 460);
  ctx.stroke();

  // === الفائز ===
  ctx.fillStyle = '#fef3e2';
  ctx.font = '700 40px "IBM Plex Sans Arabic", sans-serif';
  ctx.fillText(isTie ? '🤝 تعادل! 🤝' : '🏆 الفائز 🏆', 540, 520);

  if (!isTie) {
    ctx.fillStyle = '#e89e54';
    ctx.font = '900 60px "IBM Plex Sans Arabic", sans-serif';
    ctx.fillText(`${winner.avatar} ${winner.name}`, 540, 600);

    // النقاط
    ctx.fillStyle = '#fef3e2';
    ctx.font = '900 80px Inter, sans-serif';
    ctx.fillText(`${winner.score.toLocaleString('ar-EG')} نقطة`, 540, 690);
  }

  // === ترتيب باقي الفرق ===
  const startY = isTie ? 600 : 770;
  sorted.forEach((team, idx) => {
    if (!isTie && idx === 0) return; // الفائز ظاهر فوق
    const y = startY + (isTie ? idx : idx - 1) * 80;
    if (y > 980) return; // ما يطلع برّا

    // خلفية الصف
    ctx.fillStyle = 'rgba(205,127,50,0.1)';
    roundRect(ctx, 200, y - 30, 680, 60, 14);
    ctx.fill();

    // الرقم
    ctx.fillStyle = idx === 0 ? '#e89e54' : '#c9a878';
    ctx.font = '700 32px "IBM Plex Sans Arabic", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(`#${idx + 1}`, 860, y);

    // الأفاتار + الاسم
    ctx.font = '600 32px "IBM Plex Sans Arabic", sans-serif';
    ctx.fillStyle = '#fef3e2';
    ctx.textAlign = 'center';
    ctx.fillText(`${team.avatar} ${team.name}`, 540, y);

    // النقاط
    ctx.fillStyle = '#e89e54';
    ctx.font = '700 32px Inter, sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText(team.score.toLocaleString('ar-EG'), 220, y);
  });

  // === علامة تجارية في الأسفل ===
  ctx.fillStyle = 'rgba(201,168,120,0.6)';
  ctx.font = '500 22px "IBM Plex Sans Arabic", sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('العب الآن على 36', 540, 1020);

  return canvas;
}

// رسم اللوغو 36 على canvas
function drawLogo36(ctx, cx, cy, size) {
  // الخلفية المربعة بـ gradient
  const halfSize = size / 2;
  const r = size * 0.2;
  const gradient = ctx.createLinearGradient(cx - halfSize, cy - halfSize, cx + halfSize, cy + halfSize);
  gradient.addColorStop(0, '#e89e54');
  gradient.addColorStop(1, '#cc5500');
  ctx.fillStyle = gradient;
  roundRect(ctx, cx - halfSize, cy - halfSize, size, size, r);
  ctx.fill();

  // الـ 12 مربع داخلي (4×3 صفوف)
  const cellSize = size * 0.14;
  const gap = size * 0.16;
  const startX = cx - 1.5 * gap - cellSize / 2;
  const startY = cy - 1.5 * gap - cellSize / 2;

  // الزوايا الأربع (مضيئة 0.95) + الباقي 0.55
  const corners = [[0,0], [3,0], [0,3], [3,3]];
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 4; col++) {
      if (row === 1 && col >= 1 && col <= 2) continue; // ما نرسم الصف الثاني الأوسط
      if (row === 2 && col >= 1 && col <= 2) continue;
      const isCorner = corners.some(([r, c]) => r === row && c === col);
      ctx.fillStyle = isCorner ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.55)';
      const x = startX + col * gap;
      const y = startY + row * gap;
      roundRect(ctx, x, y, cellSize, cellSize, cellSize * 0.15);
      ctx.fill();
    }
  }
}

// helper لرسم مستطيل بزوايا دائرية
function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
  ctx.lineTo(x + w, y + h - r);
  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  ctx.lineTo(x + r, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

