function renderStats() {
  const history = State.gameHistory || [];
  const totalGames = history.length;
  return `
    <div class="screen">
      <div class="arena-header">
        <button class="btn btn-ghost btn-sm" onclick="navigate('home')">‹ رجوع</button>
        <h2 class="arena-header-title">سجل الألعاب</h2>
        <div style="width:60px"></div>
      </div>

      ${totalGames === 0 ? `
        <div class="card" style="text-align:center;padding:40px">
          <div style="font-size:70px;margin-bottom:16px">📊</div>
          <div style="color:var(--text-dim);font-weight:500;line-height:1.7">
            لا توجد ألعاب سابقة بعد<br/>
            ابدأ لعبة وستظهر إحصائياتك هنا!
          </div>
        </div>
      ` : `
        <div class="card" style="text-align:center;margin-bottom:16px;padding:24px">
          <div style="font-family:'IBM Plex Sans Arabic',sans-serif;font-size:64px;background:linear-gradient(135deg,var(--bronze-light),var(--bronze));-webkit-background-clip:text;-webkit-text-fill-color:transparent;line-height:1;font-weight:700">${totalGames}</div>
          <div style="color:var(--text-dim);margin-top:8px;font-weight:600">إجمالي الألعاب</div>
        </div>
        <h3 class="title-sm" style="margin:20px 0 10px">📜 آخر الألعاب</h3>
        ${history.slice(0, 10).map(g => {
          const d = new Date(g.date);
          return `
            <div class="card" style="margin-bottom:10px;padding:14px">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
                <div style="font-weight:700">🏆 ${escapeHtml(g.winner)}</div>
                <div style="font-size:12px;color:var(--text-mute);font-weight:500">${d.toLocaleDateString('ar-EG')}</div>
              </div>
              <div style="display:flex;gap:8px;font-size:13px;color:var(--text-dim);font-weight:500;flex-wrap:wrap">
                ${g.teams.map(t => `<span>${t.avatar} ${escapeHtml(t.name)}: ${t.score}</span>`).join(' • ')}
              </div>
            </div>
          `;
        }).join('')}
        <button class="btn btn-danger btn-full" onclick="clearHistory()" style="margin-top:20px">🗑️ مسح التاريخ</button>
      `}
    </div>
  `;
}

function clearHistory() {
  if (!confirm('مسح كل التاريخ؟')) return;
  State.gameHistory = [];
  try { localStorage.removeItem('esalni_v6_history'); } catch(e) {}
  render();
}

// ============================================================
// Admin - مبسط
// ============================================================
function renderAdmin() {
  const tab = adminState.tab;
  let content = '';
  if (tab === 'list') content = renderAdminList();
  else if (tab === 'tools') content = renderAdminTools();
  else if (tab === 'stats') content = renderAdminStats();

  return `
    <div class="screen">
      <div class="arena-header">
        <button class="btn btn-ghost btn-sm" onclick="navigate('home')">‹ رجوع</button>
        <h2 class="arena-header-title">بنك الأسئلة</h2>
        <div style="width:60px"></div>
      </div>
      <div class="warning-banner">
        <span>⚠️</span>
        <div>راجع المحتوى قبل النشر. التعديلات تُحفظ محلياً.</div>
      </div>
      <div style="display:flex;gap:8px;border-bottom:1.5px solid var(--border-warm);margin-bottom:20px;overflow-x:auto">
        <button onclick="adminState.tab='list';render()" style="padding:12px 18px;background:transparent;border:0;border-bottom:3px solid ${tab==='list'?'var(--bronze)':'transparent'};color:${tab==='list'?'var(--bronze-light)':'var(--text-dim)'};font-family:inherit;font-weight:700;cursor:pointer;font-size:15px">📋 الأسئلة</button>
        <button onclick="adminState.tab='tools';render()" style="padding:12px 18px;background:transparent;border:0;border-bottom:3px solid ${tab==='tools'?'var(--bronze)':'transparent'};color:${tab==='tools'?'var(--bronze-light)':'var(--text-dim)'};font-family:inherit;font-weight:700;cursor:pointer;font-size:15px">🛠️ أدوات</button>
        <button onclick="adminState.tab='stats';render()" style="padding:12px 18px;background:transparent;border:0;border-bottom:3px solid ${tab==='stats'?'var(--bronze)':'transparent'};color:${tab==='stats'?'var(--bronze-light)':'var(--text-dim)'};font-family:inherit;font-weight:700;cursor:pointer;font-size:15px">📊 إحصاء</button>
      </div>
      ${content}
      ${adminState.editingIdx !== null ? renderEditModal() : ''}
      ${adminState.newCat ? renderNewCategoryModal() : ''}
    </div>
  `;
}

function renderAdminList() {
  const list = State.questionsDB[adminState.selectedCat] || [];
  const filtered = adminState.search
    ? list.filter(q => (q.q || '').includes(adminState.search) || (q.a || '').includes(adminState.search))
    : list;
  const itemsHtml = filtered.slice(0, 30).map((q, idx) => {
    const realIdx = list.indexOf(q);
    return `
      <div class="card" style="margin-bottom:10px;padding:14px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
          <span class="badge badge-warm">${q.pts || 200} نقطة</span>
          <div style="display:flex;gap:6px">
            <button class="btn btn-sm btn-secondary" onclick="editQuestion(${realIdx})">✏️</button>
            <button class="btn btn-sm btn-danger" onclick="deleteQuestion(${realIdx})">🗑️</button>
          </div>
        </div>
        <div style="font-size:15px;font-weight:700;line-height:1.6;margin:6px 0">${escapeHtml(q.q || '')}</div>
        <div style="font-size:14px;color:#6ee7b7;font-weight:500">✓ ${escapeHtml(q.a || '')}</div>
      </div>
    `;
  }).join('');

  const selCat = CATEGORIES.find(c => c.id === adminState.selectedCat);
  const isCustomCat = selCat && selCat.isCustom;

  return `
    <button class="btn btn-secondary btn-full" onclick="openNewCategory()" style="margin-bottom:12px">✨ إنشاء فئة جديدة خاصة بك</button>
    <select onchange="adminState.selectedCat=this.value;render()" style="margin-bottom:12px">
      ${CATEGORIES.map(c => `<option value="${c.id}" ${c.id === adminState.selectedCat ? 'selected' : ''}>${c.isCustom ? '⭐ ' : ''}${c.name} (${(State.questionsDB[c.id]||[]).length})</option>`).join('')}
    </select>
    ${isCustomCat ? `<button class="btn btn-sm btn-danger btn-full" onclick="deleteCustomCategory('${selCat.id}')" style="margin-bottom:12px">🗑️ حذف فئة "${escapeHtml(selCat.name)}"</button>` : ''}
    <input type="text" placeholder="🔍 بحث..." value="${escapeHtml(adminState.search)}" oninput="adminState.search=this.value;render()" style="margin-bottom:12px"/>
    <button class="btn btn-primary btn-full" onclick="addNewQuestion()" style="margin-bottom:16px">+ إضافة سؤال جديد</button>
    <div style="font-size:14px;color:var(--text-dim);margin-bottom:10px;font-weight:500">عرض ${Math.min(filtered.length, 30)} من ${list.length}</div>
    ${itemsHtml}
  `;
}

function renderAdminTools() {
  // حساب التغطية الإجمالية للأسئلة المطروحة
  let totalQ = 0, totalSeen = 0;
  CATEGORIES.forEach(cat => { const c = getCoverage(cat.id); totalQ += c.total; totalSeen += c.seen; });
  const seenPct = totalQ ? Math.round(totalSeen / totalQ * 100) : 0;
  return `
    <div class="card" style="margin-bottom:14px">
      <h3 class="title-sm" style="margin-bottom:12px">🆕 تجديد الأسئلة</h3>
      <div style="font-size:13px;color:var(--text-dim);font-weight:500;margin-bottom:10px">
        طُرح <strong style="color:var(--bronze-light)">${totalSeen}</strong> من <strong>${totalQ}</strong> سؤال (${seenPct}%). الأسئلة الجديدة تُقدَّم تلقائياً في كل جولة، وتُعاد تدويرها عند نفادها.
      </div>
      <div class="cat-fresh-bar" style="height:10px;margin-bottom:12px"><div class="cat-fresh-fill" style="width:${seenPct}%;background:var(--bronze-light)"></div></div>
      <button class="btn btn-secondary btn-full" onclick="resetSeenQuestions()">♻️ تصفير الأسئلة المطروحة (ابدأ من جديد)</button>
    </div>
    <div class="card" style="margin-bottom:14px"><h3 class="title-sm" style="margin-bottom:12px">📤 التصدير</h3><button class="btn btn-secondary btn-full" onclick="exportData()">تصدير JSON</button></div>
    <div class="card" style="margin-bottom:14px"><h3 class="title-sm" style="margin-bottom:12px">🎨 تبديل الثيم</h3><button class="btn btn-secondary btn-full" onclick="toggleTheme()">${State.theme === 'girls' ? '👑 الرجالي' : '🌸 البناتي'}</button></div>
    <div class="card" style="margin-bottom:14px"><h3 class="title-sm" style="margin-bottom:12px">🔄 إعادة الضبط</h3><button class="btn btn-danger btn-full" onclick="resetAll()">إعادة ضبط كل شيء</button></div>
  `;
}

function resetSeenQuestions() {
  if (!confirm('تصفير سجلّ الأسئلة المطروحة؟ ستعود كل الأسئلة لتُعتبر جديدة.')) return;
  resetSeen();
  showToast('♻️ تم تصفير الأسئلة المطروحة — كل الأسئلة جديدة الآن');
  render();
}

function renderAdminStats() {
  const total = Object.values(State.questionsDB).reduce((s, arr) => s + arr.length, 0);
  return `
    <div class="card" style="text-align:center;margin-bottom:14px;padding:24px">
      <div style="font-family:'IBM Plex Sans Arabic',sans-serif;font-size:64px;background:linear-gradient(135deg,var(--bronze-light),var(--bronze));-webkit-background-clip:text;-webkit-text-fill-color:transparent;line-height:1;font-weight:700">${total}</div>
      <div style="color:var(--text-dim);margin-top:8px;font-weight:600">إجمالي الأسئلة</div>
    </div>
    ${CATEGORIES.map(cat => {
      const list = State.questionsDB[cat.id] || [];
      return `
        <div class="card" style="margin-bottom:8px;padding:14px;border-right:4px solid ${cat.color}">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div style="font-weight:700;font-size:15px;display:flex;align-items:center;gap:10px">
              <span style="display:inline-flex;color:${cat.color}">${getCategoryIcon(cat.id, 22, cat.color)}</span>
              ${cat.name}
            </div>
            <div style="color:var(--bronze-light);font-family:'IBM Plex Sans Arabic',sans-serif;font-size:24px;font-weight:700">${list.length}</div>
          </div>
        </div>
      `;
    }).join('')}
  `;
}

function renderEditModal() {
  const f = adminState.editForm;
  if (!f) return '';
  const isNew = adminState.editingIdx === 'new';
  return `
    <div class="modal-overlay" onclick="closeEditModal()">
      <div class="modal-content" onclick="event.stopPropagation()">
        <h3 class="title-md" style="text-align:center;margin-bottom:18px">${isNew ? 'سؤال جديد' : 'تعديل السؤال'}</h3>
        <label>السؤال</label>
        <textarea id="ef-q" rows="3">${escapeHtml(f.q)}</textarea>
        <label style="margin-top:14px">الإجابة الصحيحة</label>
        <input id="ef-a" value="${escapeHtml(f.a)}"/>
        <label style="margin-top:14px">إجابات خاطئة (3)</label>
        ${[0,1,2].map(i => `<input id="ef-w${i}" value="${escapeHtml(f.wrong[i] || '')}" placeholder="خاطئة ${i+1}" style="margin-bottom:6px"/>`).join('')}
        <label style="margin-top:14px">التلميح (اختياري)</label>
        <input id="ef-hint" value="${escapeHtml(f.hint || '')}"/>
        <label style="margin-top:14px">النقاط</label>
        <select id="ef-pts">
          <option value="100" ${f.pts === 100 ? 'selected' : ''}>100 (سهل)</option>
          <option value="200" ${f.pts === 200 || !f.pts ? 'selected' : ''}>200 (متوسط)</option>
          <option value="400" ${f.pts === 400 ? 'selected' : ''}>400 (صعب)</option>
          <option value="500" ${f.pts === 500 ? 'selected' : ''}>500 (صعب جداً)</option>
          <option value="600" ${f.pts === 600 ? 'selected' : ''}>600 (خبير)</option>
        </select>
        <div style="display:flex;gap:10px;margin-top:22px">
          <button class="btn btn-primary btn-full" onclick="saveEditModal()">${isNew ? '➕ إضافة' : '💾 حفظ'}</button>
          <button class="btn btn-ghost btn-full" onclick="closeEditModal()">إلغاء</button>
        </div>
      </div>
    </div>
  `;
}

function editQuestion(idx) {
  const q = State.questionsDB[adminState.selectedCat][idx];
  adminState.editingIdx = idx;
  adminState.editForm = { q: q.q, a: q.a, wrong: [...(q.wrong || ['','',''])], hint: q.hint || '', pts: q.pts || 200 };
  render();
}

function addNewQuestion() {
  adminState.editingIdx = 'new';
  adminState.editForm = { q: '', a: '', wrong: ['','',''], hint: '', pts: 200 };
  render();
}

function closeEditModal() {
  adminState.editingIdx = null;
  adminState.editForm = null;
  render();
}

function saveEditModal() {
  const f = {
    q: document.getElementById('ef-q').value.trim(),
    a: document.getElementById('ef-a').value.trim(),
    wrong: [document.getElementById('ef-w0').value.trim(), document.getElementById('ef-w1').value.trim(), document.getElementById('ef-w2').value.trim()],
    hint: document.getElementById('ef-hint').value.trim(),
    pts: parseInt(document.getElementById('ef-pts').value),
  };
  if (!f.q || !f.a) { showToast('السؤال والإجابة مطلوبان'); return; }
  const cat = adminState.selectedCat;
  if (!State.questionsDB[cat]) State.questionsDB[cat] = [];
  if (adminState.editingIdx === 'new') State.questionsDB[cat].push(f);
  else State.questionsDB[cat][adminState.editingIdx] = f;
  saveCustom();
  closeEditModal();
}

function deleteQuestion(idx) {
  if (!confirm('حذف هذا السؤال نهائياً؟')) return;
  State.questionsDB[adminState.selectedCat].splice(idx, 1);
  saveCustom();
  render();
}

function saveCustom() {
  try {
    localStorage.setItem('esalni_v6_custom', JSON.stringify(State.questionsDB));
    showToast('تم الحفظ ✓');
  } catch(e) { showToast('فشل الحفظ'); }
}

// ===== محرر الفئات المخصصة =====
const CUSTOM_CAT_ICONS = ['🎯','🔥','💎','🎲','🎮','🎪','🏆','👑','🌟','🎨','🎭','🎸','⚡','🚀','🧠','❤️'];
const CUSTOM_CAT_COLORS = ['#3b82f6','#ef4444','#10b981','#f97316','#8b5cf6','#ec4899','#06b6d4','#eab308'];

function openNewCategory() {
  adminState.newCat = { name: '', icon: '🎯', color: '#8b5cf6' };
  render();
}
function closeNewCategory() {
  adminState.newCat = null;
  render();
}
function renderNewCategoryModal() {
  const c = adminState.newCat;
  if (!c) return '';
  return `
    <div class="modal-overlay" onclick="closeNewCategory()">
      <div class="modal-content" onclick="event.stopPropagation()">
        <h3 class="title-md" style="text-align:center;margin-bottom:18px">✨ فئة جديدة</h3>
        <label>اسم الفئة</label>
        <input id="nc-name" value="${escapeHtml(c.name)}" placeholder="مثال: أسئلة شلتنا، ذكرياتنا..."/>
        <label style="margin-top:14px">اختر أيقونة</label>
        <div class="cat-icon-picker">
          ${CUSTOM_CAT_ICONS.map(ic => `<button class="cat-icon-opt ${c.icon===ic?'selected':''}" onclick="adminState.newCat.icon='${ic}';render()">${ic}</button>`).join('')}
        </div>
        <label style="margin-top:14px">اختر لوناً</label>
        <div class="cat-color-picker">
          ${CUSTOM_CAT_COLORS.map(col => `<button class="cat-color-opt ${c.color===col?'selected':''}" style="background:${col}" onclick="adminState.newCat.color='${col}';render()"></button>`).join('')}
        </div>
        <div style="background:var(--bg-card);border-radius:12px;padding:12px;margin-top:16px;text-align:center">
          <span style="font-size:32px">${c.icon}</span>
          <div style="color:var(--text);font-weight:700;margin-top:4px">${escapeHtml(c.name || 'اسم الفئة')}</div>
        </div>
        <div style="display:flex;gap:10px;margin-top:22px">
          <button class="btn btn-primary btn-full" onclick="createCategory()">➕ إنشاء</button>
          <button class="btn btn-ghost btn-full" onclick="closeNewCategory()">إلغاء</button>
        </div>
      </div>
    </div>
  `;
}
function createCategory() {
  const name = document.getElementById('nc-name').value.trim();
  if (!name) { showToast('اكتب اسم الفئة'); return; }
  const id = 'custom_' + Date.now();
  CATEGORIES.push({ id, name, icon: adminState.newCat.icon, color: adminState.newCat.color, isCustom: true });
  State.questionsDB[id] = [];
  saveCustomCategories();
  saveCustom();
  adminState.selectedCat = id;
  adminState.newCat = null;
  showToast('تم إنشاء الفئة ✓ أضف أسئلتها الآن');
  render();
}
function deleteCustomCategory(id) {
  if (!confirm('حذف هذه الفئة وكل أسئلتها نهائياً؟')) return;
  CATEGORIES = CATEGORIES.filter(c => c.id !== id);
  delete State.questionsDB[id];
  saveCustomCategories();
  saveCustom();
  adminState.selectedCat = CATEGORIES[0].id;
  showToast('تم حذف الفئة');
  render();
}

function exportData() {
  const data = { questions: State.questionsDB, history: State.gameHistory, theme: State.theme };
  const blob = new Blob([JSON.stringify(data, null, 2)], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `esalni-v6-${Date.now()}.json`;
  a.click();
  URL.revokeObjectURL(url);
  showToast('تم التصدير ✓');
}

function resetAll() {
  if (!confirm('حذف كل التعديلات والتاريخ؟')) return;
  ['esalni_v6_custom', 'esalni_v6_history', 'esalni_v6_theme', 'esalni_v6_seen_onboarding', 'esalni_v6_seen_q'].forEach(k => {
    try { localStorage.removeItem(k); } catch(e) {}
  });
  location.reload();
}

