function showWelcome() {
  const app = document.getElementById('app');
  if (!app) return;
  const totalQ = Object.values(State.questionsDB || {}).reduce((s, arr) => s + arr.length, 0);
  const overlay = document.createElement('div');
  overlay.className = 'welcome-screen';
  overlay.id = 'welcome-overlay';
  overlay.innerHTML = `
    <div class="welcome-logo">${typeof getLogo === 'function' ? getLogo(96) : '🎯'}</div>
    <h1 class="welcome-title">36</h1>
    <div class="welcome-sub">سؤال المجلس</div>
    <p class="welcome-msg">جاهز للتحدي؟ اجمع أصحابك، اختر فريقك، وأثبت من صاحب أقوى معلومة في المجلس. أسئلة أصعب، مكافآت أسرع، وسلاسل تشعل الحماس! 🔥</p>
    <div class="welcome-chips">
      <span class="welcome-chip">🧠 ${totalQ.toLocaleString('ar-EG')}+ سؤال</span>
      <span class="welcome-chip">⚡ مكافآت سرعة</span>
      <span class="welcome-chip">🔥 سلاسل نقاط</span>
      <span class="welcome-chip">🎬 صور مع كل سؤال</span>
    </div>
    <button class="welcome-cta" onclick="dismissWelcome()">🚀 ابدأ التحدي</button>
  `;
  app.appendChild(overlay);
}
function dismissWelcome() {
  if (typeof playSound === 'function') playSound('click');
  const overlay = document.getElementById('welcome-overlay');
  if (!overlay) return;
  overlay.classList.add('leaving');
  setTimeout(() => { if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay); }, 480);
}

// ============================================================
// Init
// ============================================================
window.addEventListener('DOMContentLoaded', () => {
  try {
    const savedTheme = localStorage.getItem('esalni_v6_theme');
    if (savedTheme) State.theme = savedTheme;
    const savedHistory = localStorage.getItem('esalni_v6_history');
    if (savedHistory) State.gameHistory = JSON.parse(savedHistory) || [];
    const seenOnboarding = localStorage.getItem('esalni_v6_seen_onboarding');
    if (seenOnboarding) State.hasSeenOnboarding = true;
    State.lastSetup = loadLastSetup();
    State.hasUnfinishedGame = !!loadGameProgress();
    loadStats();
  } catch(e) {}

  applyTheme(State.theme);
  loadCustomCategories();
  loadSeen();
  State.questionsDB = buildQuestionsDB();
  State.modesDB = buildModesDB();

  if (State.hasSeenOnboarding) State.screen = 'hub';
  else State.screen = 'theme-select';

  render();
  showWelcome();
});

